/* ------------------------------------------------------------------ */
/* Row events. */
/* ------------------------------------------------------------------ */

interface LineRef {
  lineIndex: number;
  lineNumber: number;
  noEOFCR: boolean;
  splitLineIndex: number;
  unifiedLineIndex: number;
}

type EventType = "change" | "context" | "context-expanded";

interface DiffEvent {
  additionLine?: LineRef;
  collapsedAfter: number;
  collapsedBefore: number;
  deletionLine?: LineRef;
  hunk?: DiffHunk;
  hunkIndex: number;
  type: EventType;
}

const collectEvents = ({
  collapsedContextThreshold,
  diff,
  diffStyle,
  expandedHunks,
}: {
  collapsedContextThreshold: number;
  diff: FileDiffMetadata;
  diffStyle: DiffStyle;
  expandedHunks: ExpandedHunks | undefined;
}): DiffEvent[] => {
  const events: DiffEvent[] = [];
  const unified = diffStyle === "unified";
  const lastHunkIndex = diff.hunks.length - 1;

  for (const [hunkIndex, hunk] of diff.hunks.entries()) {
    const deletionIndex = hunkIndexStart(
      hunk.deletionStart,
      hunk.deletionCount
    );

    const additionIndex = hunkIndexStart(
      hunk.additionStart,
      hunk.additionCount
    );

    const expansion = resolveHunkExpansion({
      collapsedContextThreshold,
      expandedHunks,
      hunkIndex,
      isPartial: diff.isPartial,
      rangeSize: hunk.collapsedBefore,
    });

    const trailing =
      hunkIndex === lastHunkIndex
        ? resolveTrailingExpansion({
            collapsedContextThreshold,
            diff,
            expandedHunks,
          })
        : undefined;

    const trailingCollapsed = (unifiedIndex: number, splitIndex: number) => {
      if (
        trailing === undefined ||
        trailing.collapsedLines <= 0 ||
        trailing.fromStart + trailing.fromEnd > 0
      ) {
        return 0;
      }

      const isLast = unified
        ? unifiedIndex === hunk.unifiedLineStart + hunk.unifiedLineCount - 1
        : splitIndex === hunk.splitLineStart + hunk.splitLineCount - 1;

      return isLast ? trailing.collapsedLines : 0;
    };

    let gapPending = expansion.collapsedLines !== 0;

    const takeGap = () => {
      if (!gapPending) {
        return 0;
      }

      gapPending = false;

      return expansion.collapsedLines;
    };

    const expandedAt = (
      count: number,
      offset: number,
      collapsedBefore: () => number
    ) => {
      const unifiedBase = hunk.unifiedLineStart - offset;
      const splitBase = hunk.splitLineStart - offset;
      const deletionLineIndex = hunk.deletionLineIndex - offset;
      const additionLineIndex = hunk.additionLineIndex - offset;
      const deletionNumber = deletionIndex + 1 - offset;
      const additionNumber = additionIndex + 1 - offset;

      for (let step = 0; step < count; step += 1) {
        events.push({
          additionLine: {
            lineIndex: additionLineIndex + step,
            lineNumber: additionNumber + step,
            noEOFCR: false,
            splitLineIndex: splitBase + step,
            unifiedLineIndex: unifiedBase + step,
          },
          collapsedAfter: 0,
          collapsedBefore: step === 0 ? collapsedBefore() : 0,
          deletionLine: {
            lineIndex: deletionLineIndex + step,
            lineNumber: deletionNumber + step,
            noEOFCR: false,
            splitLineIndex: splitBase + step,
            unifiedLineIndex: unifiedBase + step,
          },
          hunk,
          hunkIndex,
          type: "context-expanded",
        });
      }
    };

    expandedAt(expansion.fromStart, expansion.rangeSize, () => 0);
    expandedAt(expansion.fromEnd, expansion.fromEnd, takeGap);

    let unifiedCursor = hunk.unifiedLineStart;
    let splitCursor = hunk.splitLineStart;
    let deletionCursor = hunk.deletionLineIndex;
    let additionCursor = hunk.additionLineIndex;
    let deletionNumber = deletionIndex + 1;
    let additionNumber = additionIndex + 1;
    const lastContent = hunk.hunkContent.at(-1);

    for (const part of hunk.hunkContent) {
      const isLastContent = part === lastContent;

      if (part.type === "context") {
        for (let step = 0; step < part.lines; step += 1) {
          const isLastLine = isLastContent && step === part.lines - 1;
          const unifiedIndex = unifiedCursor + step;
          const splitIndex = splitCursor + step;
          events.push({
            additionLine: {
              lineIndex: additionCursor + step,
              lineNumber: additionNumber + step,
              noEOFCR: isLastLine && hunk.noEOFCRAdditions,
              splitLineIndex: splitIndex,
              unifiedLineIndex: unifiedIndex,
            },
            collapsedAfter: trailingCollapsed(unifiedIndex, splitIndex),
            collapsedBefore: takeGap(),
            deletionLine: {
              lineIndex: deletionCursor + step,
              lineNumber: deletionNumber + step,
              noEOFCR: isLastLine && hunk.noEOFCRDeletions,
              splitLineIndex: splitIndex,
              unifiedLineIndex: unifiedIndex,
            },
            hunk,
            hunkIndex,
            type: "context",
          });
        }

        unifiedCursor += part.lines;
        splitCursor += part.lines;
        deletionCursor += part.lines;
        additionCursor += part.lines;
        deletionNumber += part.lines;
        additionNumber += part.lines;
      } else {
        const splitCount = Math.max(part.deletions, part.additions);
        const unifiedCount = part.deletions + part.additions;
        const total = unified ? unifiedCount : splitCount;

        for (let step = 0; step < total; step += 1) {
          const hasDeletion = step < part.deletions;
          const additionStep = unified ? step - part.deletions : step;

          const hasAddition = unified
            ? step >= part.deletions
            : step < part.additions;

          const splitIndex =
            splitCursor + (unified && !hasDeletion ? additionStep : step);

          const deletionUnified = hasDeletion
            ? unifiedCursor + step
            : undefined;

          const additionUnified = hasAddition
            ? unifiedCursor + part.deletions + additionStep
            : undefined;

          const lastLineOfBlock = unified
            ? step === unifiedCount - 1
            : step === splitCount - 1;

          const deletionNoEOF = unified
            ? isLastContent &&
              step === part.deletions - 1 &&
              hunk.noEOFCRDeletions
            : isLastContent && lastLineOfBlock && hunk.noEOFCRDeletions;

          const additionNoEOF =
            isLastContent && lastLineOfBlock ? hunk.noEOFCRAdditions : false;

          events.push({
            additionLine:
              hasAddition && additionUnified !== undefined
                ? {
                    lineIndex: additionCursor + additionStep,
                    lineNumber: additionNumber + additionStep,
                    noEOFCR: additionNoEOF,
                    splitLineIndex: splitIndex,
                    unifiedLineIndex: additionUnified,
                  }
                : undefined,
            collapsedAfter: trailingCollapsed(unifiedCursor + step, splitIndex),
            collapsedBefore: takeGap(),
            deletionLine:
              hasDeletion && deletionUnified !== undefined
                ? {
                    lineIndex: deletionCursor + step,
                    lineNumber: deletionNumber + step,
                    noEOFCR: deletionNoEOF,
                    splitLineIndex: splitIndex,
                    unifiedLineIndex: deletionUnified,
                  }
                : undefined,
            hunk,
            hunkIndex,
            type: "change",
          });
        }

        takeGap();
        unifiedCursor += unifiedCount;
        splitCursor += splitCount;
        deletionCursor += part.deletions;
        additionCursor += part.additions;
        deletionNumber += part.deletions;
        additionNumber += part.additions;
      }
    }

    if (trailing !== undefined) {
      const shown = trailing.fromStart + trailing.fromEnd;

      for (let step = 0; step < shown; step += 1) {
        const line = {
          splitLineIndex: splitCursor + step,
          unifiedLineIndex: unifiedCursor + step,
        };

        events.push({
          additionLine: {
            ...line,
            lineIndex: additionCursor + step,
            lineNumber: additionNumber + step,
            noEOFCR: false,
          },
          collapsedAfter: step === shown - 1 ? trailing.collapsedLines : 0,
          collapsedBefore: 0,
          deletionLine: {
            ...line,
            lineIndex: deletionCursor + step,
            lineNumber: deletionNumber + step,
            noEOFCR: false,
          },
          hunkIndex: diff.hunks.length,
          type: "context-expanded",
        });
      }
    }
  }

  return events;
};

/* ------------------------------------------------------------------ */
/* Rendering                                                           */
/* ------------------------------------------------------------------ */

type ColumnKind = "additions" | "deletions" | "unified";

interface Column {
  content: ReactNode[];
  gutter: ReactNode[];
}

interface Rows {
  additions: Column;
  deletions: Column;
  rowCount: number;
  unified: Column;
}

interface BufferState {
  side: AnnotationSide | undefined;
  size: number;
}

interface HoverState {
  annotationSide: AnnotationSide;
  column: ColumnKind;
  indexAttribute: string;
  lineNumber: number;
  lineType: string;
}

const EXPAND_ICONS = {
  both: LucideChevronsUpDown,
  plus: LucidePlus,
  single: LucideChevronDown,
} as const;

const Icon = ({ icon: Glyph }: { icon: LucideIcon }) => (
  <Glyph data-icon="" size={16} strokeWidth={1.5} />
);

const attr = (value: boolean | undefined) => (value === true ? "" : undefined);

const lineSide = (column: ColumnKind, lineType: string): AnnotationSide => {
  if (column === "deletions" || lineType === "change-deletion") {
    return "deletions";
  }

  return "additions";
};

interface BuildInput<T> {
  annotations: ReadonlyMap<string, DiffLineAnnotation<T>[]>;
  contextMessage: ContextMessage | undefined;
  contextTarget: ContextTarget | undefined;
  decorations: ReadonlyMap<string, DiffSpan[]>;
  diff: FileDiffMetadata;
  diffStyle: DiffStyle;
  enableGutterUtility: boolean;
  events: readonly DiffEvent[];
  expandable: boolean;
  expansionLineCount: number;
  hover: HoverState | null;
  hunkSeparators: HunkSeparators;
  lineHoverHighlight: LineHoverHighlight;
  partialLoader: boolean;
  renderAnnotation:
    | ((annotation: DiffLineAnnotation<T>) => ReactNode)
    | undefined;
  syntaxThemes: SyntaxThemes;
  tokens: DiffTokens | undefined;
  trailingUnknown: boolean;
  utility: UtilityTarget | null;
}

const renderLineText = (
  text: string,
  spans: readonly DiffSpan[] | undefined,
  tokens: readonly RoleToken[] | undefined,
  syntaxThemes: SyntaxThemes
): ReactNode => {
  if (text === "") {
    return "\n";
  }

  if (tokens !== undefined) {
    const highlighted = renderTokenLine(text, tokens, spans, syntaxThemes);

    if (highlighted !== undefined) {
      return highlighted;
    }
  }

  if (!spans || spans.length === 0) {
    return <span data-char="">{text}</span>;
  }

  const parts: ReactNode[] = [];
  let position = 0;

  for (const span of spans) {
    if (span.start > position) {
      parts.push(text.slice(position, span.start));
    }

    parts.push(
      <span data-diff-span="" key={`${span.start}:${span.length}`}>
        {text.slice(span.start, span.start + span.length)}
      </span>
    );
    position = span.start + span.length;
  }

  if (position < text.length) {
    parts.push(text.slice(position));
  }

  return <span data-char="">{parts}</span>;
};

const separatorKeyFor = (column: ColumnKind, index: number | string) =>
  `separator:${column}:${index}`;

const BUTTON_CONTROLS = {
  both: "data-ck-expand-both",
  down: "data-ck-expand-down",
  up: "data-ck-expand-up",
} as const satisfies Record<"both" | "down" | "up", ContextControl>;

/** One separator element, with the app's loading/error label state. */
const renderSeparator = ({
  chunked,
  content,
  contextMessage,
  contextTarget,
  expandIndex,
  isFirstHunk,
  isLastHunk,
  key,
  type,
}: {
  chunked: boolean;
  content: string | undefined;
  contextMessage: ContextMessage | undefined;
  contextTarget: ContextTarget | undefined;
  expandIndex: number | undefined;
  isFirstHunk: boolean;
  isLastHunk: boolean;
  key: string;
  type: HunkSeparators;
}) => {
  const active =
    contextMessage !== undefined &&
    contextTarget !== undefined &&
    expandIndex !== undefined &&
    contextTarget.index === String(expandIndex);

  const pendingControl = active ? contextTarget.control : undefined;
  const isLoading = active && contextMessage.status === "loading";
  const showMessage = active && pendingControl !== undefined;

  if (type === "metadata" && content !== undefined) {
    return (
      <div
        data-separator="metadata"
        data-separator-first={attr(isFirstHunk)}
        data-separator-last={attr(isLastHunk)}
        key={key}
      >
        <div data-separator-wrapper="">{content}</div>
      </div>
    );
  }

  const isLineInfo = type === "line-info" || type === "line-info-basic";

  if (!(isLineInfo && content !== undefined)) {
    return (
      <div
        data-separator="simple"
        data-separator-first={attr(isFirstHunk)}
        data-separator-last={attr(isLastHunk)}
        key={key}
      />
    );
  }

  const buttons: ("both" | "down" | "up")[] = [];

  if (expandIndex !== undefined) {
    if (chunked) {
      if (!isFirstHunk) {
        buttons.push("up");
      }

      if (!isLastHunk) {
        buttons.push("down");
      }
    } else if (!isFirstHunk && !isLastHunk) {
      buttons.push("both");
    } else {
      buttons.push(isFirstHunk ? "down" : "up");
    }
  }

  return (
    <div
      data-ck-expand-index={expandIndex}
      data-separator={type}
      data-separator-first={attr(isFirstHunk)}
      data-separator-last={attr(isLastHunk)}
      key={key}
    >
      <div
        data-separator-multi-button={attr(buttons.length > 1)}
        data-separator-wrapper=""
      >
        {buttons.map((kind) => (
          <div
            data-ck-context-pending={attr(
              isLoading && pendingControl === BUTTON_CONTROLS[kind]
            )}
            data-ck-expand-both={attr(kind === "both")}
            data-ck-expand-button=""
            data-ck-expand-down={attr(kind === "down")}
            data-ck-expand-up={attr(kind === "up")}
            key={kind}
            role="button"
          >
            <Icon
              icon={kind === "both" ? EXPAND_ICONS.both : EXPAND_ICONS.single}
            />
          </div>
        ))}
        <div data-separator-content="">
          <span
            data-ck-unmodified-lines=""
            hidden={showMessage ? true : undefined}
          >
            {content}
          </span>
          {showMessage ? (
            <span
              data-ck-context-label-pending={attr(
                isLoading && pendingControl === "data-ck-unmodified-lines"
              )}
              data-ck-context-message={contextMessage.status}
            >
              {contextMessage.label}
              {contextMessage.status === "error" ? (
                <>
                  {" "}
                  <button data-ck-context-retry="" type="button">
                    {contextMessage.retry}
                  </button>
                </>
              ) : null}
            </span>
          ) : null}
        </div>
        {chunked && expandIndex !== undefined ? (
          <div
            data-ck-expand-all-button=""
            data-ck-expand-button=""
            role="button"
          >
            Expand all
          </div>
        ) : null}
      </div>
    </div>
  );
};

const trailingRangeSize = (diff: FileDiffMetadata) => {
  const last = diff.hunks.at(-1);

  if (!last || diff.isPartial) {
    return 0;
  }

  return Math.max(
    Math.min(
      diff.additionLines.length -
        (hunkIndexStart(last.additionStart, last.additionCount) +
          last.additionCount),
      diff.deletionLines.length -
        (hunkIndexStart(last.deletionStart, last.deletionCount) +
          last.deletionCount)
    ),
    0
  );
};

const buildRows = <T,>(input: BuildInput<T>): Rows => {
  const {
    annotations,
    contextMessage,
    contextTarget,
    decorations,
    diff,
    diffStyle,
    enableGutterUtility,
    events,
    expandable,
    expansionLineCount,
    hover,
    hunkSeparators,
    lineHoverHighlight,
    partialLoader,
    renderAnnotation,
    syntaxThemes,
    tokens,
    trailingUnknown,
    utility,
  } = input;

  const unified = diffStyle === "unified";

  const rows: Rows = {
    additions: { content: [], gutter: [] },
    deletions: { content: [], gutter: [] },
    rowCount: 0,
    unified: { content: [], gutter: [] },
  };

  const buffer: BufferState = { side: undefined, size: 0 };

  let counter = 0;

  const nextKey = (prefix: string) => {
    counter += 1;

    return `${prefix}:${counter}`;
  };

  const flush = () => {
    if (unified) {
      return;
    }

    if (buffer.size <= 0 || buffer.side === undefined) {
      buffer.side = undefined;
      buffer.size = 0;

      return;
    }

    const column =
      buffer.side === "additions" ? rows.additions : rows.deletions;

    const { size } = buffer;
    column.gutter.push(
      <div
        data-ck-buffer-size={size}
        data-gutter-buffer="buffer"
        key={nextKey("gb")}
        style={{
          gridRow: `span ${size}`,
          minHeight: `calc(${size} * 1lh)`,
        }}
      />
    );
    column.content.push(
      <div
        data-ck-buffer-size={size}
        data-content-buffer=""
        key={nextKey("cb")}
        style={{
          gridRow: `span ${size}`,
          minHeight: `calc(${size} * 1lh)`,
        }}
      />
    );
    buffer.size = 0;
    buffer.side = undefined;
  };

  const pushSeparator = (
    column: ColumnKind,
    options: {
      chunked: boolean;
      content: string | undefined;
      expandIndex: number | undefined;
      isFirstHunk: boolean;
      isLastHunk: boolean;
      key: string;
      type: HunkSeparators;
    }
  ) => {
    const gutterElement = renderSeparator({
      ...options,
      contextMessage,
      contextTarget,
      key: `${options.key}:g`,
    });

    const contentElement = renderSeparator({
      ...options,
      contextMessage,
      contextTarget,
      key: `${options.key}:c`,
    });

    rows[column].gutter.push(gutterElement);
    rows[column].content.push(contentElement);

    if (column !== "additions") {
      rows.rowCount += 1;
    }
  };

  const emitSeparator = (info: {
    lines: number | null;
    hunkIndex: number;
    hunkSpecs: string | undefined;
    isFirstHunk: boolean;
    isLastHunk: boolean;
    rangeSize: number;
  }) => {
    if (info.lines !== null && info.lines <= 0) {
      return;
    }

    flush();

    const columns: ColumnKind[] = unified
      ? ["unified"]
      : ["deletions", "additions"];

    for (const column of columns) {
      const key = separatorKeyFor(column, nextKey("s"));

      if (hunkSeparators === "metadata") {
        if (info.hunkSpecs !== undefined) {
          pushSeparator(column, {
            chunked: false,
            content: info.hunkSpecs,
            expandIndex: undefined,
            isFirstHunk: info.isFirstHunk,
            isLastHunk: info.isLastHunk,
            key,
            type: "metadata",
          });
        }
      } else if (hunkSeparators === "simple") {
        if (info.hunkIndex > 0) {
          pushSeparator(column, {
            chunked: false,
            content: undefined,
            expandIndex: undefined,
            isFirstHunk: info.isFirstHunk,
            isLastHunk: false,
            key,
            type: "simple",
          });
        }
      } else {
        pushSeparator(column, {
          chunked: info.rangeSize > expansionLineCount,
          content:
            info.lines === null
              ? "More unchanged context may be available"
              : unmodifiedLinesLabel(info.lines),
          expandIndex: expandable ? info.hunkIndex : undefined,
          isFirstHunk: info.isFirstHunk,
          isLastHunk: info.isLastHunk,
          key,
          type: hunkSeparators,
        });
      }
    }
  };

  const numberCell = ({
    column,
    indexAttribute,
    lineNumber,
    lineType,
  }: {
    column: ColumnKind;
    indexAttribute: string;
    lineNumber: number;
    lineType: string;
  }) => {
    const isHovered =
      hover?.column === column &&
      hover.indexAttribute === indexAttribute &&
      (lineHoverHighlight === "both" || lineHoverHighlight === "number");

    const showsUtility =
      enableGutterUtility &&
      utility?.column === column &&
      utility.indexAttribute === indexAttribute;

    return (
      <div
        data-ck-column-number={lineNumber}
        data-hovered={attr(isHovered)}
        data-line-index={indexAttribute}
        data-line-type={lineType}
        key={`n:${column}:${indexAttribute}`}
      >
        <span data-line-number-content="">{lineNumber}</span>
        {showsUtility ? (
          <div
            data-gutter-utility-slot=""
            style={{
              bottom: 0,
              position: "absolute",
              textAlign: "center",
              top: 0,
              touchAction: "none",
              whiteSpace: "normal",
            }}
          >
            <button data-ck-utility-button="" type="button">
              <Icon icon={EXPAND_ICONS.plus} />
            </button>
          </div>
        ) : null}
      </div>
    );
  };

  const lineElement = ({
    altLine,
    column,
    indexAttribute,
    lineNumber,
    lineType,
    spans,
    text,
    tokens: lineTokens,
  }: {
    altLine: number | undefined;
    column: ColumnKind;
    indexAttribute: string;
    lineNumber: number;
    lineType: string;
    spans: readonly DiffSpan[] | undefined;
    text: string;
    tokens: readonly RoleToken[] | undefined;
  }) => {
    const isHovered =
      hover?.column === column &&
      hover.indexAttribute === indexAttribute &&
      (lineHoverHighlight === "both" || lineHoverHighlight === "line");

    return (
      <div
        data-ck-alt-line={altLine}
        data-hovered={attr(isHovered)}
        data-line={lineNumber}
        data-line-index={indexAttribute}
        data-line-type={lineType}
        key={`l:${column}:${indexAttribute}`}
      >
        {renderLineText(text, spans, lineTokens, syntaxThemes)}
      </div>
    );
  };

  const annotationRow = (
    column: ColumnKind,
    lineType: string,
    items: readonly DiffLineAnnotation<T>[],
    pairKey: string
  ) => {
    rows[column].gutter.push(
      <div
        data-ck-buffer-size={1}
        data-gutter-buffer="annotation"
        key={nextKey("ag")}
        style={{ gridRow: "span 1" }}
      />
    );
    rows[column].content.push(
      <div
        data-annotation-pair={pairKey}
        data-line-annotation=""
        data-line-type={lineType}
        key={nextKey("ac")}
      >
        <div data-ck-annotation-content="">
          {items.map((item, index) => (
            <div
              data-ck-annotation-slot=""
              key={`${item.side}:${item.lineNumber}:${index}`}
              style={{ whiteSpace: "normal" }}
            >
              {renderAnnotation?.(item)}
            </div>
          ))}
        </div>
      </div>
    );
  };

  const annotationsFor = (
    deletionNumber: number | undefined,
    additionNumber: number | undefined
  ) => {
    const deletionItems =
      deletionNumber === undefined
        ? []
        : (annotations.get(`deletions:${deletionNumber}`) ?? []);

    const additionItems =
      additionNumber === undefined
        ? []
        : (annotations.get(`additions:${additionNumber}`) ?? []);

    return { additionItems, deletionItems };
  };

  const lastHunkIndex = diff.hunks.length - 1;

  for (const event of events) {
    const { additionLine, deletionLine, hunk, hunkIndex, type } = event;

    if (!unified && type !== "change") {
      flush();
    }

    if (event.collapsedBefore > 0) {
      emitSeparator({
        hunkIndex,
        hunkSpecs: hunk?.hunkSpecs,
        isFirstHunk: hunkIndex === 0,
        isLastHunk: false,
        lines: event.collapsedBefore,
        rangeSize: Math.max(hunk?.collapsedBefore ?? 0, 0),
      });
    }

    const deletionText =
      deletionLine === undefined
        ? undefined
        : stripLineEnding(diff.deletionLines[deletionLine.lineIndex] ?? "");

    const additionText =
      additionLine === undefined
        ? undefined
        : stripLineEnding(diff.additionLines[additionLine.lineIndex] ?? "");

    const deletionSpans =
      deletionLine === undefined
        ? undefined
        : decorations.get(`d:${deletionLine.lineIndex}`);

    const additionSpans =
      additionLine === undefined
        ? undefined
        : decorations.get(`a:${additionLine.lineIndex}`);

    const splitIndex =
      additionLine?.splitLineIndex ?? deletionLine?.splitLineIndex ?? 0;

    // The side that lacks a line, which receives the buffer.
    const oneSided: AnnotationSide | undefined =
      type === "change" &&
      (additionLine === undefined) !== (deletionLine === undefined)
        ? additionLine === undefined
          ? "additions"
          : "deletions"
        : undefined;

    if (unified) {
      const unifiedIndex =
        additionLine?.unifiedLineIndex ?? deletionLine?.unifiedLineIndex ?? 0;

      const lineType =
        type === "change"
          ? additionLine === undefined
            ? "change-deletion"
            : "change-addition"
          : type;

      const indexAttribute = `${unifiedIndex},${splitIndex}`;
      const number = additionLine?.lineNumber ?? deletionLine?.lineNumber ?? 0;
      const useAddition = additionLine !== undefined;
      rows.unified.gutter.push(
        numberCell({
          column: "unified",
          indexAttribute,
          lineNumber: number,
          lineType,
        })
      );
      rows.unified.content.push(
        lineElement({
          altLine: useAddition ? deletionLine?.lineNumber : undefined,
          column: "unified",
          indexAttribute,
          lineNumber: number,
          lineType,
          spans: useAddition ? additionSpans : deletionSpans,
          text: (useAddition ? additionText : deletionText) ?? "",
          tokens: useAddition
            ? tokens?.additions[additionLine.lineIndex]
            : tokens?.deletions[deletionLine?.lineIndex ?? -1],
        })
      );

      const found = annotationsFor(
        deletionLine?.lineNumber,
        additionLine?.lineNumber
      );

      const items = [...found.deletionItems, ...found.additionItems];

      if (items.length > 0) {
        annotationRow(
          "unified",
          type === "change"
            ? additionLine === undefined
              ? "change-deletion"
              : "change-addition"
            : type,
          items,
          `u:${indexAttribute}`
        );
        rows.rowCount += 1;
      }
    } else {
      if (oneSided === undefined) {
        if (type === "change") {
          flush();
        }
      } else {
        if (buffer.side !== undefined && buffer.side !== oneSided) {
          flush();
        }

        buffer.side = oneSided;
        buffer.size += 1;
      }

      const found = annotationsFor(
        deletionLine?.lineNumber,
        additionLine?.lineNumber
      );

      const hasAnnotations =
        found.deletionItems.length > 0 || found.additionItems.length > 0;

      if (hasAnnotations && buffer.size > 0) {
        flush();
      }

      if (deletionLine !== undefined) {
        const lineType = type === "change" ? "change-deletion" : type;
        const indexAttribute = `${deletionLine.unifiedLineIndex},${splitIndex}`;
        rows.deletions.gutter.push(
          numberCell({
            column: "deletions",
            indexAttribute,
            lineNumber: deletionLine.lineNumber,
            lineType,
          })
        );
        rows.deletions.content.push(
          lineElement({
            altLine: undefined,
            column: "deletions",
            indexAttribute,
            lineNumber: deletionLine.lineNumber,
            lineType,
            spans: deletionSpans,
            text: deletionText ?? "",
            tokens: tokens?.deletions[deletionLine.lineIndex],
          })
        );
      }

      if (additionLine !== undefined) {
        const lineType = type === "change" ? "change-addition" : type;
        const indexAttribute = `${additionLine.unifiedLineIndex},${splitIndex}`;
        rows.additions.gutter.push(
          numberCell({
            column: "additions",
            indexAttribute,
            lineNumber: additionLine.lineNumber,
            lineType,
          })
        );
        rows.additions.content.push(
          lineElement({
            altLine: undefined,
            column: "additions",
            indexAttribute,
            lineNumber: additionLine.lineNumber,
            lineType,
            spans: additionSpans,
            text: additionText ?? "",
            tokens: tokens?.additions[additionLine.lineIndex],
          })
        );
      }

      if (hasAnnotations) {
        const pairKey = `s:${splitIndex}:${event.hunkIndex}`;
        annotationRow(
          "deletions",
          type === "change"
            ? deletionLine
              ? "change-deletion"
              : "context"
            : type,
          found.deletionItems,
          pairKey
        );
        annotationRow(
          "additions",
          type === "change"
            ? additionLine
              ? "change-addition"
              : "context"
            : type,
          found.additionItems,
          pairKey
        );
        rows.rowCount += 1;
      }
    }

    const isHunkLastSplit =
      !unified &&
      hunk !== undefined &&
      splitIndex === hunk.splitLineStart + hunk.splitLineCount - 1;

    const isHunkLastUnified =
      unified &&
      hunk !== undefined &&
      (additionLine?.unifiedLineIndex ??
        deletionLine?.unifiedLineIndex ??
        0) ===
        hunk.unifiedLineStart + hunk.unifiedLineCount - 1;

    const isLastLineOfLastHunk =
      hunkIndex === lastHunkIndex &&
      hunk !== undefined &&
      (unified ? isHunkLastUnified : isHunkLastSplit);

    const deletionMissing =
      (deletionLine?.noEOFCR ?? false) ||
      (isHunkLastSplit && hunk.noEOFCRDeletions);

    const additionMissing =
      (additionLine?.noEOFCR ?? false) ||
      (isHunkLastSplit && hunk.noEOFCRAdditions);

    if (additionMissing || deletionMissing) {
      if (!unified) {
        flush();
      }

      const noNewline = (column: ColumnKind, lineType: string) => {
        rows[column].content.push(
          <div
            data-ck-column-content=""
            data-line-type={lineType}
            data-ck-no-newline=""
            key={nextKey("nn")}
          >
            <span>No newline at end of file</span>
          </div>
        );
        rows[column].gutter.push(
          <div
            data-ck-buffer-size={1}
            data-gutter-buffer="metadata"
            data-line-type={lineType}
            key={nextKey("ng")}
            style={{ gridRow: "span 1", minHeight: "calc(1 * 1lh)" }}
          />
        );
      };

      const spacer = (column: ColumnKind) => {
        rows[column].gutter.push(
          <div
            data-ck-buffer-size={1}
            data-gutter-buffer="buffer"
            key={nextKey("sg")}
            style={{ gridRow: "span 1", minHeight: "calc(1 * 1lh)" }}
          />
        );
        rows[column].content.push(
          <div
            data-ck-buffer-size={1}
            data-content-buffer=""
            key={nextKey("sc")}
            style={{ gridRow: "span 1", minHeight: "calc(1 * 1lh)" }}
          />
        );
      };

      const contextual = type === "context" || type === "context-expanded";

      if (deletionMissing) {
        const lineType = contextual ? type : "change-deletion";
        noNewline(unified ? "unified" : "deletions", lineType);

        if (!(unified || additionMissing)) {
          spacer("additions");
        }
      }

      if (additionMissing) {
        const lineType = contextual ? type : "change-addition";
        noNewline(unified ? "unified" : "additions", lineType);

        if (!(unified || deletionMissing)) {
          spacer("deletions");
        }
      }

      rows.rowCount += 1;
    }

    const trailingSeparator =
      hunkSeparators !== "simple" &&
      hunkSeparators !== "metadata" &&
      (event.collapsedAfter > 0 ||
        (isLastLineOfLastHunk && trailingUnknown && partialLoader));

    if (trailingSeparator) {
      emitSeparator({
        hunkIndex: type === "context-expanded" ? hunkIndex : hunkIndex + 1,
        hunkSpecs: undefined,
        isFirstHunk: false,
        isLastHunk: true,
        lines:
          isLastLineOfLastHunk && trailingUnknown && partialLoader
            ? null
            : event.collapsedAfter,
        rangeSize: trailingRangeSize(diff),
      });
    }

    rows.rowCount += 1;
  }

  if (!unified) {
    flush();
  }

  return rows;
};

/** Word-level spans per line, keyed `d:<index>` and `a:<index>`. */
const computeDecorations = (
  diff: FileDiffMetadata,
  lineDiffType: LineDiffType,
  maxLineDiffLength: number | undefined
) => {
  const map = new Map<string, DiffSpan[]>();

  if (lineDiffType === "none") {
    return map;
  }

  for (const hunk of diff.hunks) {
    for (const part of hunk.hunkContent) {
      if (part.type !== "change") {
        continue;
      }

      const pairs = Math.min(part.deletions, part.additions);

      for (let step = 0; step < pairs; step += 1) {
        const deletionLine = diff.deletionLines[part.deletionLineIndex + step];
        const additionLine = diff.additionLines[part.additionLineIndex + step];

        if (deletionLine === undefined || additionLine === undefined) {
          continue;
        }

        const result = diffLinePair(
          deletionLine,
          additionLine,
          lineDiffType,
          maxLineDiffLength
        );

        if (result) {
          map.set(`d:${part.deletionLineIndex + step}`, result.deletions);
          map.set(`a:${part.additionLineIndex + step}`, result.additions);
        }
      }
    }
  }

  return map;
};

const CONTEXT_CONTROLS: readonly ContextControl[] = [
  "data-ck-expand-up",
  "data-ck-expand-down",
  "data-ck-expand-both",
  "data-ck-expand-all-button",
  "data-ck-unmodified-lines",
];

/** The expander under the pointer, found from the click target. */
const findContextTarget = (
  target: EventTarget | null,
  shiftKey: boolean
): ContextTarget | undefined => {
  let element: Element | null = target instanceof Element ? target : null;
  let control: ContextControl | undefined;

  while (element !== null) {
    if (control === undefined) {
      const current = element;
      control = CONTEXT_CONTROLS.find((name) => current.hasAttribute(name));
    }

    const index = element.getAttribute("data-ck-expand-index");

    if (control !== undefined && index !== null) {
      return { control, index, shiftKey };
    }

    if (element.hasAttribute("data-code")) {
      return undefined;
    }

    element = element.parentElement;
  }

  return undefined;
};

const columnOf = (element: Element): ColumnKind | undefined => {
  const code = element.closest("[data-code]");

  if (!code) {
    return undefined;
  }

  if (code.hasAttribute("data-unified")) {
    return "unified";
  }

  if (code.hasAttribute("data-deletions")) {
    return "deletions";
  }

  return code.hasAttribute("data-additions") ? "additions" : undefined;
};

const SCROLL_SYNC_RELEASE_MS = 300;

const controlDirection = (control: ContextControl): ExpandDirection => {
  if (control === "data-ck-expand-up") {
    return "up";
  }

  if (control === "data-ck-expand-down") {
    return "down";
  }

  return "both";
};

export const DiffView = <T,>({
  alignCommentGutter = false,
  className,
  collapsedContextThreshold = 1,
  codeThemes,
  contextMessage,
  contextTarget,
  diffIndicators = "bars",
  diffStyle = "split",
  disableBackground = false,
  disableLineNumbers = false,
  enableGutterUtility = false,
  enableLineSelection = false,
  expandUnchanged = false,
  expansionLineCount = 100,
  fileDiff,
  hunkSeparators = "line-info",
  lineAnnotations,
  lineDiffType = "word-alt",
  lineHoverHighlight = "disabled",
  loadDiffFiles,
  maxLineDiffLength,
  onContextExpand,
  onGutterUtilityClick,
  onLineClick,
  onLineEnter,
  onLineLeave,
  onLineNumberClick,
  onLineSelected,
  onLineSelectionChange,
  onLineSelectionEnd,
  onLineSelectionStart,
  onPostRender,
  overflow = "scroll",
  renderAnnotation,
  reviewLineInfoSeparators = false,
  selectedLines,
  selectedLinesOptions,
  simpleLineSeparators = false,
  style,
  themeType,
  tokenizeMaxLength,
  tokenizeMaxLineLength,
}: DiffViewProps<T>) => {
  const hostRef = useRef<HTMLDivElement>(null);

  const [expanded, setExpanded] = useState<ReadonlyMap<number, ExpandedRange>>(
    () => new Map()
  );

  const [hydrated, setHydrated] = useState<{
    source: FileDiffMetadata;
    value: FileDiffMetadata;
  } | null>(null);

  const [hover, setHover] = useState<HoverState | null>(null);

  const preRef = useRef<HTMLPreElement>(null);

  const [selectionView, setSelectionView] = useState<SelectionView>({
    highlightSide: undefined,
    lineNumberOnly: false,
    range: null,
  });

  const [utility, setUtility] = useState<UtilityTarget | null>(null);
  const hoverRef = useRef<HoverState | null>(null);

  const pendingLoadRef = useRef<FileDiffMetadata | null>(null);

  const diff =
    hydrated !== null && hydrated.source === fileDiff
      ? hydrated.value
      : fileDiff;

  const isControlled = selectedLines !== undefined;

  const canLoad =
    diff.isPartial &&
    loadDiffFiles !== undefined &&
    (diff.type === "change" ||
      diff.type === "rename-changed" ||
      diff.type === "rename-pure");

  const expandable = !diff.isPartial || canLoad;

  const effectiveExpanded: ExpandedHunks | undefined = expandUnchanged
    ? true
    : expanded;

  const split = diffStyle === "split";

  const events = useMemo(
    () =>
      collectEvents({
        collapsedContextThreshold,
        diff,
        diffStyle,
        expandedHunks: effectiveExpanded,
      }),
    [collapsedContextThreshold, diff, diffStyle, effectiveExpanded]
  );

  const decorations = useMemo(
    () => computeDecorations(diff, lineDiffType, maxLineDiffLength),
    [diff, lineDiffType, maxLineDiffLength]
  );

  const tokens = useDiffTokens(diff, {
    tokenizeMaxLength,
    tokenizeMaxLineLength,
  });

  const syntaxThemes = useCodeThemes(codeThemes);

  const annotations = useMemo(() => {
    const map = new Map<string, DiffLineAnnotation<T>[]>();

    for (const annotation of lineAnnotations ?? []) {
      const key = `${annotation.side}:${annotation.lineNumber}`;
      map.set(key, [...(map.get(key) ?? []), annotation]);
    }

    return map;
  }, [lineAnnotations]);

  const rows = useMemo(
    () =>
      buildRows<T>({
        annotations,
        contextMessage,
        contextTarget,
        decorations,
        diff,
        diffStyle,
        enableGutterUtility,
        events,
        expandable,
        expansionLineCount,
        hover,
        hunkSeparators,
        lineHoverHighlight,
        partialLoader: canLoad,
        renderAnnotation,
        syntaxThemes,
        tokens,
        trailingUnknown: canLoad,
        utility,
      }),
    [
      annotations,
      canLoad,
      contextMessage,
      contextTarget,
      decorations,
      diff,
      diffStyle,
      enableGutterUtility,
      events,
      expandable,
      expansionLineCount,
      hover,
      hunkSeparators,
      lineHoverHighlight,
      renderAnnotation,
      syntaxThemes,
      tokens,
      utility,
    ]
  );

  /** The rendered row indexes (unified, split) of each line, by side and line number. */
  const lineIndexes = useMemo(() => {
    const map = new Map<string, readonly [number, number]>();

    for (const event of events) {
      const row =
        event.additionLine?.splitLineIndex ??
        event.deletionLine?.splitLineIndex ??
        0;

      if (event.additionLine) {
        map.set(`additions:${event.additionLine.lineNumber}`, [
          event.additionLine.unifiedLineIndex,
          row,
        ]);
      }

      if (event.deletionLine) {
        map.set(`deletions:${event.deletionLine.lineNumber}`, [
          event.deletionLine.unifiedLineIndex,
          row,
        ]);
      }
    }

    return map;
  }, [events]);

  const getLineIndex = useCallback(
    (lineNumber: number, side: AnnotationSide) =>
      lineIndexes.get(`${side}:${lineNumber}`) ?? null,
    [lineIndexes]
  );

  const selection = useMemo(
    () =>
      new LineSelectionController({
        controlledSelection: false,
        enableGutterUtility: false,
        enableLineSelection: false,
        getHovered: noTarget,
        getLineIndex: noIndex,
        onUtilityChange: ignoreTarget,
        onViewChange: ignoreView,
      }),
    []
  );

  const totalLines = Math.max(
    diff.hunks.length === 0
      ? 0
      : hunkIndexStart(
          diff.hunks.at(-1)?.additionStart ?? 0,
          diff.hunks.at(-1)?.additionCount ?? 0
        ) + (diff.hunks.at(-1)?.additionCount ?? 0),
    diff.additionLines.length,
    diff.deletionLines.length
  );

  const loadFull = useCallback(() => {
    if (
      !canLoad ||
      loadDiffFiles === undefined ||
      pendingLoadRef.current === diff
    ) {
      return;
    }

    pendingLoadRef.current = diff;
    const source = diff;

    const run = async () => {
      try {
        const { newFile, oldFile } = await loadDiffFiles(source);

        if (pendingLoadRef.current === source) {
          setHydrated({ source, value: createFileDiff(oldFile, newFile) });
        }
      } catch {
        // The tracker around loadDiffFiles reports the failure.
      }

      if (pendingLoadRef.current === source) {
        pendingLoadRef.current = null;
      }
    };

    run().catch(ignoreRejection);
  }, [canLoad, diff, loadDiffFiles]);

  const expandHunk = useCallback(
    (hunkIndex: number, direction: ExpandDirection, count: number) => {
      loadFull();
      setExpanded((previous) => {
        const next = new Map(previous);

        const range = {
          ...(next.get(hunkIndex) ?? { fromEnd: 0, fromStart: 0 }),
        };

        if (direction === "up" || direction === "both") {
          range.fromStart += count;
        }

        if (direction === "down" || direction === "both") {
          range.fromEnd += count;
        }

        next.set(hunkIndex, range);

        return next;
      });
    },
    [loadFull]
  );

  const handleClick = (event: ReactMouseEvent<HTMLDivElement>) => {
    const target = event.target instanceof Element ? event.target : null;

    // With onGutterUtilityClick, a click that comes from the
    // gutter utility is its own action (the pointer session), not a line or
    // number click.
    if (
      onGutterUtilityClick !== undefined &&
      target?.closest("[data-ck-utility-button], [data-gutter-utility-slot]")
    ) {
      return;
    }

    if (target?.closest("[data-ck-context-retry]")) {
      if (contextTarget) {
        event.stopPropagation();
        onContextExpand?.({
          ...contextTarget,
          shiftKey: contextTarget.shiftKey,
        });
        const index = Number(contextTarget.index);

        const all =
          contextTarget.control === "data-ck-expand-all-button" ||
          contextTarget.shiftKey;

        expandHunk(
          index,
          all ? "both" : controlDirection(contextTarget.control),
          all ? Number.POSITIVE_INFINITY : expansionLineCount
        );
      }

      return;
    }

    const context = findContextTarget(event.target, event.shiftKey);

    if (context) {
      onContextExpand?.(context);

      const all =
        context.control === "data-ck-expand-all-button" || event.shiftKey;

      expandHunk(
        Number(context.index),
        all ? "both" : controlDirection(context.control),
        all ? Number.POSITIVE_INFINITY : expansionLineCount
      );

      return;
    }

    const cell = target?.closest("[data-line], [data-ck-column-number]");

    if (!(cell instanceof HTMLElement)) {
      return;
    }

    const column = columnOf(cell);

    if (!column) {
      return;
    }

    const lineNumber = Number(cell.dataset.line ?? cell.dataset.ckColumnNumber);

    const lineType = cell.dataset.lineType ?? "context";

    const props: DiffLineEventProps = {
      annotationSide: lineSide(column, lineType),
      event,
      lineNumber,
      lineType,
    };

    if (cell.hasAttribute("data-ck-column-number") && onLineNumberClick) {
      onLineNumberClick(props);
    } else {
      onLineClick?.(props);
    }
  };

  const showsHover = lineHoverHighlight !== "disabled" || enableGutterUtility;

  const handlePointerOver = (event: ReactPointerEvent<HTMLDivElement>) => {
    // Pierre `handlePointerMove`: only a mouse hovers a line.
    if (event.pointerType !== "mouse") {
      return;
    }

    const target = event.target instanceof Element ? event.target : null;
    const cell = target?.closest("[data-line], [data-ck-column-number]");

    const hoverEnabled =
      lineHoverHighlight !== "disabled" ||
      enableGutterUtility ||
      onLineEnter !== undefined ||
      onLineLeave !== undefined;

    if (!hoverEnabled) {
      return;
    }

    if (!(cell instanceof HTMLElement)) {
      return;
    }

    const column = columnOf(cell);
    const indexAttribute = cell.dataset.lineIndex;

    if (!column || indexAttribute === undefined) {
      return;
    }

    const hovered = hoverRef.current;

    if (
      hovered?.column === column &&
      hovered.indexAttribute === indexAttribute
    ) {
      return;
    }

    const lineType = cell.dataset.lineType ?? "context";

    const lineNumber = Number(cell.dataset.line ?? cell.dataset.ckColumnNumber);

    const next: HoverState = {
      annotationSide: lineSide(column, lineType),
      column,
      indexAttribute,
      lineNumber,
      lineType,
    };

    if (hovered) {
      onLineLeave?.({
        annotationSide: hovered.annotationSide,
        event,
        lineNumber: hovered.lineNumber,
        lineType: hovered.lineType,
      });
    }

    hoverRef.current = next;

    // The rows only change for the hover highlight and the gutter utility.
    if (showsHover) {
      setHover(next);
    }

    selection.placeUtility();
    onLineEnter?.({
      annotationSide: next.annotationSide,
      event,
      lineNumber,
      lineType,
    });
  };

  const handlePointerLeave = (event: ReactPointerEvent<HTMLDivElement>) => {
    const hovered = hoverRef.current;

    if (hovered) {
      onLineLeave?.({
        annotationSide: hovered.annotationSide,
        event,
        lineNumber: hovered.lineNumber,
        lineType: hovered.lineType,
      });
      hoverRef.current = null;

      if (showsHover) {
        setHover(null);
      }

      selection.placeUtility();
    }
  };

  const handlePointerDown = (event: ReactPointerEvent<HTMLDivElement>) => {
    selection.handlePointerDown(event.nativeEvent);
  };

  // The controller reads the latest props and the rendered <pre>.
  useLayoutEffect(() => {
    selection.setOptions({
      controlledSelection: isControlled,
      enableGutterUtility,
      enableLineSelection,
      getHovered: () => {
        const { current } = hoverRef;

        return current === null
          ? null
          : {
              column: current.column,
              indexAttribute: current.indexAttribute,
              lineNumber: current.lineNumber,
              side: current.annotationSide,
            };
      },
      getLineIndex,
      onGutterUtilityClick,
      onLineSelected,
      onLineSelectionChange,
      onLineSelectionEnd,
      onLineSelectionStart,
      onUtilityChange: (target) => {
        setUtility((previous) =>
          previous?.column === target?.column &&
          previous?.indexAttribute === target?.indexAttribute
            ? previous
            : target
        );
      },
      onViewChange: setSelectionView,
    });
  }, [
    enableGutterUtility,
    enableLineSelection,
    getLineIndex,
    isControlled,
    onGutterUtilityClick,
    onLineSelected,
    onLineSelectionChange,
    onLineSelectionEnd,
    onLineSelectionStart,
    selection,
  ]);

  useLayoutEffect(() => {
    selection.setup(preRef.current);
    // oxlint-disable-next-line react/exhaustive-effect-dependencies -- the pre element and its rows are re-read whenever the rendered rows change.
  }, [rows, selection]);

  useEffect(
    () => () => {
      selection.cleanUp();
    },
    [selection]
  );

  // A `selectedLines` prop sets the rendered range.
  useLayoutEffect(() => {
    if (isControlled) {
      selection.setSelection(selectedLines, {
        ...selectedLinesOptions,
        notify: false,
      });
    }
  }, [isControlled, selection, selectedLines, selectedLinesOptions]);

  // Marks the cells of the selected rows after each render.
  useLayoutEffect(() => {
    if (preRef.current) {
      renderSelection(preRef.current, selectionView, getLineIndex);
    }
    // oxlint-disable-next-line react/exhaustive-effect-dependencies -- the cells are replaced when the rows change, so the marks are drawn again.
  }, [getLineIndex, rows, selectionView]);

  // The two split panes scroll together.
  useEffect(() => {
    const host = hostRef.current;

    if (!(host && split && overflow === "scroll")) {
      return noCleanup;
    }

    const deletions = host.querySelector<HTMLElement>("[data-deletions]");
    const additions = host.querySelector<HTMLElement>("[data-additions]");

    if (!(deletions && additions)) {
      return noCleanup;
    }

    let deletionsActive = false;
    let additionsActive = false;
    let timer: ReturnType<typeof setTimeout> | undefined;

    const onDeletions = () => {
      if (additionsActive) {
        return;
      }

      // oxlint-disable-next-line react/immutability -- local to this effect or callback, not render state; oxlint 1.91 misreports it
      deletionsActive = true;
      clearTimeout(timer);
      timer = setTimeout(() => {
        deletionsActive = false;
      }, SCROLL_SYNC_RELEASE_MS);
      additions.scrollTo({ left: deletions.scrollLeft });
    };

    const onAdditions = () => {
      if (deletionsActive) {
        return;
      }

      additionsActive = true;
      clearTimeout(timer);
      timer = setTimeout(() => {
        additionsActive = false;
      }, SCROLL_SYNC_RELEASE_MS);
      deletions.scrollTo({ left: additions.scrollLeft });
    };

    deletions.addEventListener("scroll", onDeletions, { passive: true });
    additions.addEventListener("scroll", onAdditions, { passive: true });

    return () => {
      clearTimeout(timer);
      deletions.removeEventListener("scroll", onDeletions);
      additions.removeEventListener("scroll", onAdditions);
    };
    // oxlint-disable-next-line react/exhaustive-effect-dependencies -- the panes are queried from the DOM, so the effect re-attaches when the rendered columns (rows) change.
  }, [split, overflow, rows]);

  // Pierre ResizeManager: column widths for sticky annotations and separators.
  useLayoutEffect(() => {
    const host = hostRef.current;

    if (!host) {
      return noCleanup;
    }

    const measure = () => {
      for (const code of host.querySelectorAll<HTMLElement>("[data-code]")) {
        const gutter = code.querySelector<HTMLElement>("[data-gutter]");
        const numberWidth = gutter?.offsetWidth ?? 0;
        const codeWidth = code.clientWidth;
        code.style.setProperty("--diffs-column-width", `${codeWidth}px`);
        code.style.setProperty(
          "--diffs-column-number-width",
          numberWidth === 0 ? "auto" : `${numberWidth}px`
        );
        const content = Math.max(codeWidth - numberWidth, 0);
        code.style.setProperty(
          "--diffs-column-content-width",
          content > 0 ? `${content}px` : "auto"
        );
      }

      // Annotation rows of the two split panes share one height.
      const pairs = new Map<string, HTMLElement[]>();

      for (const element of host.querySelectorAll<HTMLElement>(
        "[data-annotation-pair]"
      )) {
        element.style.removeProperty("--diffs-annotation-min-height");
        const key = element.dataset.annotationPair ?? "";
        pairs.set(key, [...(pairs.get(key) ?? []), element]);
      }

      for (const members of pairs.values()) {
        if (members.length < 2) {
          continue;
        }

        const height = Math.max(
          ...members.map((member) => member.offsetHeight)
        );

        for (const member of members) {
          member.style.setProperty(
            "--diffs-annotation-min-height",
            `${height}px`
          );
        }
      }
    };

    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(host);

    return () => {
      observer.disconnect();
    };
    // oxlint-disable-next-line react/exhaustive-effect-dependencies -- the columns are queried from the DOM, so the measurement re-runs when the rendered rows change.
  }, [rows]);

  useLayoutEffect(() => {
    if (hostRef.current) {
      onPostRender?.(hostRef.current);
    }
  });

  const showCode = rows.rowCount > 0;
  const hasUnified = diffStyle === "unified";
  const showDeletions = !hasUnified && diff.type !== "new" && showCode;
  const showAdditions = !hasUnified && diff.type !== "deleted" && showCode;
  const containerSize = hunkSeparators === "line-info";

  const preStyle: CustomStyle = {
    "--diffs-min-number-column-width-default": `${String(totalLines).length}ch`,
  };

  const renderCode = (kind: ColumnKind, column: Column) => (
    <code
      data-additions={attr(kind === "additions")}
      data-code=""
      data-ck-container-size={attr(containerSize)}
      data-deletions={attr(kind === "deletions")}
      data-unified={attr(kind === "unified")}
    >
      <div data-gutter="" style={{ gridRow: `span ${rows.rowCount}` }}>
        {column.gutter}
      </div>
      <div data-content="" style={{ gridRow: `span ${rows.rowCount}` }}>
        {column.content}
      </div>
    </code>
  );

  return (
    // oxlint-disable-next-line jsx-a11y/click-events-have-key-events -- Pierre delegates pointer events on the host; its expanders and line cells have no keyboard handler, and the focusable controls inside (retry, gutter button, annotations) are native elements.
    <div
      className={cn(
        styles.root,
        alignCommentGutter && styles.alignCommentGutter,
        reviewLineInfoSeparators && styles.reviewLineInfo,
        simpleLineSeparators && styles.simpleLine,
        themeType === "system" && styles.system,
        // The app's scope classes set color-scheme and the light-dark toggles.
        themeType === "light" && "light",
        themeType === "dark" && "dark",
        className
      )}
      data-diffs-container=""
      role="presentation"
      onClick={handleClick}
      onPointerDown={handlePointerDown}
      onPointerLeave={handlePointerLeave}
      onPointerOver={handlePointerOver}
      ref={hostRef}
      style={style}
    >
      <pre
        data-background={attr(!disableBackground)}
        data-diff=""
        data-diff-type={hasUnified ? "single" : "split"}
        data-ck-disable-line-numbers={attr(disableLineNumbers)}
        data-indicators={diffIndicators === "none" ? undefined : diffIndicators}
        data-interactive-line-numbers={attr(
          onLineNumberClick !== undefined || enableLineSelection
        )}
        data-interactive-lines={attr(onLineClick !== undefined)}
        data-overflow={overflow}
        ref={preRef}
        style={preStyle}
      >
        {hasUnified && showCode ? renderCode("unified", rows.unified) : null}
        {showDeletions ? renderCode("deletions", rows.deletions) : null}
        {showAdditions ? renderCode("additions", rows.additions) : null}
      </pre>
    </div>
  );
};

/* oxlint-disable react/no-class-component -- an error boundary can only be a class component. */

import { Component } from "react";
import type { ReactNode } from "react";

interface BoundaryProps {
  children: ReactNode;
  fallback: ReactNode;
  resetKey: string;
}

interface BoundaryState {
  failed: boolean;
  key: string;
}

/**
 * A render failure shows the
 * fallback until `resetKey` changes.
 */
export class DiffErrorBoundary extends Component<BoundaryProps, BoundaryState> {
  constructor(props: BoundaryProps) {
    super(props);
    this.state = { failed: false, key: props.resetKey };
  }

  static getDerivedStateFromError(): Partial<BoundaryState> {
    return { failed: true };
  }

  static getDerivedStateFromProps(
    props: BoundaryProps,
    state: BoundaryState
  ): Partial<BoundaryState> | null {
    return props.resetKey === state.key
      ? null
      : { failed: false, key: props.resetKey };
  }

  // oxlint-disable-next-line typescript/promise-function-async -- render returns ReactNode, whose type includes promises; React renders it synchronously here.
  render() {
    return this.state.failed ? this.props.fallback : this.props.children;
  }
}

"use client";

/* oxlint-disable shadcn/no-inline-styles -- the component sets the icon color inline from its token; here it is a custom property read by a class. */

import { useEffect } from "react";
import type { CSSProperties } from "react";

import {
  FILE_ICON_BY_EXTENSION,
  FILE_ICON_BY_FILE_NAME,
  FILE_ICON_SYMBOLS,
  FILE_ICON_VARIANT_BY_EXTENSION,
} from "./file-type-icon-data";

// Maps, so a name such as "constructor" is not read from the object prototype.
const TOKEN_BY_FILE_NAME = new Map(Object.entries(FILE_ICON_BY_FILE_NAME));
const TOKEN_BY_EXTENSION = new Map(Object.entries(FILE_ICON_BY_EXTENSION));

const VARIANT_BY_EXTENSION = new Map(
  Object.entries(FILE_ICON_VARIANT_BY_EXTENSION)
);

const COLOR_NAME_BY_TOKEN = new Map<string, keyof typeof COLORS>();

/*
 * The file-type icon of the full-review header.
 * The app configures no tables of its own, so the "complete" built-in set decides.
 */

/** The colors of the icon tokens, as light and dark pairs. */
const COLORS = {
  blue: "light-dark(#1a85d4, #69b1ff)",
  cyan: "light-dark(#1ca1c7, #68cdf2)",
  gray: "light-dark(#84848a, #adadb1)",
  green: "light-dark(#199f43, #5ecc71)",
  indigo: "light-dark(#693acf, #9d6afb)",
  mauve: "light-dark(#594c5b, #79697b)",
  orange: "light-dark(#d47628, #ffa359)",
  pink: "light-dark(#d32a61, #ff678d)",
  purple: "light-dark(#a631be, #d568ea)",
  red: "light-dark(#d52c36, #ff6762)",
  teal: "light-dark(#17a5af, #64d1db)",
  vermilion: "light-dark(#ff8c5b, #d5512f)",
  yellow: "light-dark(#d5a910, #ffd452)",
} as const;

type ColorName = keyof typeof COLORS;

/** The color name of each icon token that has one. */
const COLOR_OF_TOKEN = {
  astro: "purple",
  babel: "yellow",
  bash: "green",
  biome: "blue",
  bootstrap: "indigo",
  browserslist: "yellow",
  bun: "mauve",
  c: "blue",
  claude: "orange",
  cpp: "blue",
  css: "indigo",
  database: "purple",
  default: "gray",
  docker: "blue",
  eslint: "indigo",
  git: "vermilion",
  go: "cyan",
  graphql: "pink",
  html: "orange",
  image: "pink",
  javascript: "yellow",
  json: "orange",
  markdown: "green",
  mcp: "teal",
  npm: "red",
  oxc: "cyan",
  postcss: "red",
  prettier: "teal",
  python: "blue",
  react: "cyan",
  ruby: "red",
  rust: "orange",
  sass: "pink",
  svelte: "red",
  svg: "orange",
  svgo: "green",
  swift: "orange",
  table: "teal",
  tailwind: "cyan",
  terraform: "indigo",
  text: "gray",
  typescript: "blue",
  vite: "purple",
  vscode: "blue",
  vue: "green",
  wasm: "indigo",
  webpack: "blue",
  yml: "red",
  zig: "orange",
  zip: "orange",
} satisfies Readonly<Record<string, ColorName>>;

for (const [token, color] of Object.entries(COLOR_OF_TOKEN)) {
  COLOR_NAME_BY_TOKEN.set(token, color);
}

const TERTIARY = "var(--ck-palette-ink-tertiary)";

/** The color of an icon token, falling back to the tertiary text color. */
export const fileIconColor = (token: string | undefined) => {
  if (token === undefined) {
    return TERTIARY;
  }

  const name = COLOR_NAME_BY_TOKEN.get(token);

  return name === undefined
    ? TERTIARY
    : `var(--ck-file-symbol-ink-${token}, var(--ck-file-symbol-ink, ${COLORS[name]}))`;
};

/** The suffixes after each dot of a name, longest first (`a.b.c` gives `b.c`, `c`). */
const extensionsOf = (name: string) => {
  const parts = name.toLowerCase().split(".");
  const extensions: string[] = [];

  for (let index = 1; index < parts.length; index += 1) {
    extensions.push(parts.slice(index).join("."));
  }

  return extensions;
};

/** For the complete set: a file name, then a variant, then an extension. */
const tokenOf = (name: string, extensions: readonly string[]) => {
  const byName = TOKEN_BY_FILE_NAME.get(name.toLowerCase());

  if (byName !== undefined) {
    return byName;
  }

  for (const extension of extensions) {
    const variant = VARIANT_BY_EXTENSION.get(extension);

    if (variant !== undefined) {
      return variant;
    }

    const byExtension = TOKEN_BY_EXTENSION.get(extension);

    if (byExtension !== undefined) {
      return byExtension;
    }
  }

  return "default";
};

/** The symbol and token of a path. */
export const resolveFileIcon = (path: string) => {
  const name = path.split("/").at(-1) ?? path;
  const token = tokenOf(name, extensionsOf(name));

  return { name: `ck-file-symbol-${token}`, token };
};

const SPRITE_ATTRIBUTE = "data-file-icon-sprite";

/** Puts the icon sprite in the document once, where `<use href="#...">` can reach its symbols. */
const ensureSprite = () => {
  if (document.querySelector(`[${SPRITE_ATTRIBUTE}]`) !== null) {
    return;
  }

  const sheet = new DOMParser().parseFromString(
    `<svg ${SPRITE_ATTRIBUTE} data-icon-sprite aria-hidden="true" width="0" height="0" style="position:absolute">${FILE_ICON_SYMBOLS.join("")}</svg>`,
    "text/html"
  ).body.firstElementChild;

  if (sheet !== null) {
    document.body.append(sheet);
  }
};

type IconStyle = CSSProperties & Record<`--${string}`, string>;

/** A 16px glyph picked from the path, colored by its token. */
export const DiffFileIcon = ({ path }: { path: string }) => {
  useEffect(() => {
    ensureSprite();
  }, []);

  const { name, token } = resolveFileIcon(path);
  const style: IconStyle = { "--diff-file-icon-color": fileIconColor(token) };

  return (
    <span
      className="size-4 shrink-0 text-(--diff-file-icon-color)"
      data-icon-token={token}
      style={style}
    >
      <svg aria-hidden className="size-4 shrink-0" viewBox="0 0 16 16">
        <use href={`#${name}`} />
      </svg>
    </span>
  );
};

/* oxlint-disable eslint/complexity -- the controller keeps one branch per InteractionManager case; splitting the pointer handlers would separate the shared session state. */
/* oxlint-disable unicorn/prefer-dom-node-dataset -- the checks run on composed-path nodes that include SVG icons, which have no `dataset` on Element; the component reads attributes with getAttribute/hasAttribute. */

/*
 * Line selection, based on the @pierre/diffs InteractionManager. The manager keeps one pointer session:
 *
 *   idle
 *   selecting                 a press on a line number, then a drag over line numbers or line text
 *   pendingSingleLineUnselect a press on the only selected line; a drag turns it into `selecting`,
 *                             a release unselects the line
 *   gutterSelecting           a press on the gutter utility button (needs onGutterUtilityClick)
 *
 * A pointer cancel ends every session. A press with Shift extends the selected range from the
 * end that is farther from the pressed line. A touch press first reveals the gutter utility on the
 * pressed number cell, and number cells use `touch-action: none` so a drag is not taken as a pan.
 */

import type { AnnotationSide, SelectedLineRange } from "./diff-view";

export type SelectionColumn = "additions" | "deletions" | "unified";

/** Where the gutter utility button sits: a number cell of one rendered column. */
export interface UtilityTarget {
  column: SelectionColumn;
  indexAttribute: string;
  lineNumber: number;
  side: AnnotationSide;
}

/** The selection as rendered: `setSelectedLines(range, { activeLineSide, lineNumberOnly })`. */
export interface SelectionView {
  highlightSide: AnnotationSide | undefined;
  lineNumberOnly: boolean;
  range: SelectedLineRange | null;
}

export interface SelectedLinesOptions {
  /** Highlights only this column of a split diff. */
  activeLineSide?: AnnotationSide;
  /** Highlights the number cells only, not the line bodies. */
  lineNumberOnly?: boolean;
  /** `false` skips the committed callback. */
  notify?: boolean;
}

interface SelectionPoint {
  lineNumber: number;
  side: AnnotationSide;
}

type PointerSession =
  | { mode: "idle" }
  | { mode: "selecting"; pointerId: number }
  | {
      anchor: SelectionPoint;
      mode: "pendingSingleLineUnselect";
      pending: SelectionPoint;
      pointerId: number;
    }
  | {
      anchor: SelectionPoint;
      current: SelectionPoint;
      mode: "gutterSelecting";
      pointerId: number;
    };

interface LineTarget {
  column: SelectionColumn;
  indexAttribute: string;
  lineNumber: number;
  numberColumn: boolean;
  side: AnnotationSide;
  splitLineIndex: number | undefined;
}

export interface LineSelectionOptions {
  enableGutterUtility: boolean;
  enableLineSelection: boolean;
  /** The row indexes (unified, split) of a rendered line. */
  getLineIndex: (
    lineNumber: number,
    side: AnnotationSide
  ) => readonly [number, number] | null;
  /** The hovered number cell, if the pointer is over one. */
  getHovered: () => UtilityTarget | null;
  onGutterUtilityClick?: (range: SelectedLineRange) => void;
  onLineSelected?: (range: SelectedLineRange | null) => void;
  onLineSelectionChange?: (range: SelectedLineRange | null) => void;
  onLineSelectionEnd?: (range: SelectedLineRange | null) => void;
  onLineSelectionStart?: (range: SelectedLineRange | null) => void;
  /** The selection is driven by the `selectedLines` prop. */
  controlledSelection: boolean;
  onUtilityChange: (target: UtilityTarget | null) => void;
  onViewChange: (view: SelectionView) => void;
}

const sameRange = (
  left: SelectedLineRange | null | undefined,
  right: SelectedLineRange | null | undefined
) =>
  left?.start === right?.start &&
  left?.end === right?.end &&
  left?.side === right?.side &&
  left?.endSide === right?.endSide;

const samePoint = (left: SelectionPoint, right: SelectionPoint) =>
  left.lineNumber === right.lineNumber && left.side === right.side;

/** The path runs through the gutter utility. */
const isUtilityPath = (path: readonly EventTarget[]) =>
  path.some(
    (node) =>
      node instanceof HTMLElement &&
      (node.hasAttribute("data-ck-utility-button") ||
        node.hasAttribute("data-gutter-utility-slot") ||
        node.getAttribute("slot") === "gutter-utility-slot" ||
        node.getAttribute("name") === "gutter-utility-slot")
  );

/** The node and its ancestors, nearest first. */
const ancestorsOf = (node: Element) => {
  const path: Node[] = [];

  for (let next: Node | null = node; next !== null; next = next.parentNode) {
    path.push(next);
  }

  return path;
};

/** The line or number cell of an element, or the cell an annotation row follows. */
const closestLineCell = (element: Element) => {
  const cell = element.closest("[data-line], [data-ck-column-number]");

  if (cell instanceof HTMLElement) {
    return cell;
  }

  const annotation = element.closest(
    '[data-line-annotation], [data-gutter-buffer="annotation"]'
  );

  if (!(annotation instanceof HTMLElement)) {
    return null;
  }

  const previous = annotation.previousElementSibling;

  return previous instanceof HTMLElement &&
    (previous.hasAttribute("data-line") ||
      previous.hasAttribute("data-ck-column-number"))
    ? previous
    : null;
};

/** The numbers of a `data-line-index` value: `unified,split`. */
const parseIndexes = (attribute: string) =>
  attribute
    .split(",")
    .filter((part) => part.trim() !== "")
    .map(Number)
    .filter((part) => Number.isFinite(part));

const LINE_TYPES = new Set([
  "change-addition",
  "change-deletion",
  "context",
  "context-expanded",
]);

const columnOf = (code: Element): SelectionColumn => {
  if (code.hasAttribute("data-deletions")) {
    return "deletions";
  }

  return code.hasAttribute("data-additions") ? "additions" : "unified";
};

/** The side of a line, from its type or else its column. */
const sideOf = (lineType: string, code: Element): AnnotationSide => {
  if (lineType === "change-deletion") {
    return "deletions";
  }

  if (lineType === "change-addition") {
    return "additions";
  }

  return code.hasAttribute("data-deletions") ? "deletions" : "additions";
};

/** The pointer target, reduced to the line and number cells selection reads. */
const resolveLineTarget = (
  path: readonly Node[],
  split: boolean
): LineTarget | null => {
  let numberElement: HTMLElement | undefined;
  let lineElement: HTMLElement | undefined;
  let code: HTMLElement | undefined;

  for (const node of path) {
    if (!(node instanceof HTMLElement)) {
      continue;
    }

    if (
      numberElement === undefined &&
      lineElement === undefined &&
      node.hasAttribute("data-ck-column-number")
    ) {
      numberElement = node;
    } else if (
      lineElement === undefined &&
      numberElement === undefined &&
      node.hasAttribute("data-line")
    ) {
      lineElement = node;
    } else if (node.hasAttribute("data-code")) {
      code = node;
      break;
    }
  }

  const cell = numberElement ?? lineElement;
  const lineType = cell?.getAttribute("data-line-type") ?? undefined;

  if (
    code === undefined ||
    cell === undefined ||
    lineType === undefined ||
    !LINE_TYPES.has(lineType)
  ) {
    return null;
  }

  const lineNumber = Number(
    cell.getAttribute(
      numberElement === undefined ? "data-line" : "data-ck-column-number"
    ) ?? Number.NaN
  );

  const indexAttribute = cell.getAttribute("data-line-index") ?? "";

  if (Number.isNaN(lineNumber)) {
    return null;
  }

  const indexes = parseIndexes(indexAttribute);

  let splitLineIndex: number | undefined;

  if (split) {
    splitLineIndex = indexes.length === 2 ? indexes[1] : undefined;
  } else {
    [splitLineIndex] = indexes;
  }

  return {
    column: columnOf(code),
    indexAttribute,
    lineNumber,
    numberColumn: numberElement !== undefined,
    side: sideOf(lineType, code),
    splitLineIndex,
  };
};

const buildSelectionRange = (
  start: number,
  end: number,
  startSide: AnnotationSide | undefined,
  endSide: AnnotationSide | undefined
): SelectedLineRange => {
  const range: SelectedLineRange = { end, start };

  if (startSide !== undefined) {
    range.side = startSide;
  }

  if (startSide !== endSide && endSide !== undefined) {
    range.endSide = endSide;
  }

  return range;
};

type PathSource = "coordinates-first" | "event-path";

/** The path from the line or number cell of an element. */
const pathFromElement = (element: Element, excludeUtility: boolean) => {
  if (excludeUtility && isUtilityPath(ancestorsOf(element))) {
    return null;
  }

  const cell = closestLineCell(element);

  return cell === null ? null : ancestorsOf(cell);
};

/** The path of the event's first element. */
const pathFromEventPath = (
  path: readonly EventTarget[],
  excludeUtility: boolean
) => {
  if (excludeUtility && isUtilityPath(path)) {
    return null;
  }

  const first = path.find((node) => node instanceof Element);

  return first instanceof Element
    ? pathFromElement(first, excludeUtility)
    : null;
};

export class LineSelectionController {
  options: LineSelectionOptions;
  pre: HTMLElement | undefined;
  /** The range that is rendered. */
  selectedRange: SelectedLineRange | null = null;
  highlightSide: AnnotationSide | undefined;
  lineNumberOnly = false;
  /** A controlled selection's drag result, until the parent sets it. */
  proposedRange: SelectedLineRange | null | undefined;
  anchor: SelectionPoint | undefined;
  session: PointerSession = { mode: "idle" };
  private documentListeners = false;

  constructor(options: LineSelectionOptions) {
    this.options = options;
  }

  setOptions(options: LineSelectionOptions) {
    this.options = options;

    const { enableLineSelection, onGutterUtilityClick } = options;

    const active =
      this.session.mode === "selecting" ||
      this.session.mode === "pendingSingleLineUnselect";

    // Switching a mode off ends its session.
    if (
      (!enableLineSelection && active) ||
      (onGutterUtilityClick === undefined &&
        this.session.mode === "gutterSelecting")
    ) {
      this.clearSession();
      this.detachDocumentListeners();
      this.anchor = undefined;
    }
  }

  setup(pre: HTMLElement | null) {
    if (pre === null) {
      this.cleanUp();

      return;
    }

    if (this.pre !== pre) {
      this.cleanUp();
      this.pre = pre;
    }

    if (
      !this.options.enableGutterUtility &&
      this.session.mode === "gutterSelecting"
    ) {
      this.clearSession();
      this.detachDocumentListeners();
    }

    this.placeUtility();
  }

  cleanUp() {
    this.pre = undefined;
    this.detachDocumentListeners();
    this.clearSession();
    this.anchor = undefined;
  }

  /** The selected lines are set from outside (`selectedLines`). */
  setSelection(
    range: SelectedLineRange | null,
    options?: SelectedLinesOptions
  ) {
    const changed = !sameRange(range, this.selectedRange);
    const lineNumberOnly = options?.lineNumberOnly ?? false;

    const optionsChanged =
      options?.activeLineSide !== this.highlightSide ||
      lineNumberOnly !== this.lineNumberOnly;

    if (!(changed || optionsChanged)) {
      return;
    }

    this.proposedRange = undefined;
    this.selectedRange = range;
    this.highlightSide = options?.activeLineSide;
    this.lineNumberOnly = lineNumberOnly;
    this.publish();
    this.placeUtility();

    if (changed && options?.notify !== false) {
      this.options.onLineSelected?.(range);
    }
  }

  private publish() {
    this.options.onViewChange({
      highlightSide: this.highlightSide,
      lineNumberOnly: this.lineNumberOnly,
      range: this.selectedRange,
    });
  }

  /* ---------------------------------------------------------------- */
  /* Pointer entry                                                     */
  /* ---------------------------------------------------------------- */

  handlePointerDown = (event: PointerEvent) => {
    if (
      (event.pointerType === "mouse" && event.button !== 0) ||
      this.pre === undefined ||
      this.session.mode !== "idle"
    ) {
      return;
    }

    const path = event.composedPath();

    if (
      isUtilityPath(path) &&
      this.options.onGutterUtilityClick !== undefined
    ) {
      this.startGutterSelection(event);

      return;
    }

    if (event.pointerType !== "mouse") {
      this.revealUtilityFromPath(path);
    }

    this.startLineSelection(event);
  };

  private isSplit() {
    return this.pre?.getAttribute("data-diff-type") === "split";
  }

  /* ---------------------------------------------------------------- */
  /* Resolving the line under the pointer                              */
  /* ---------------------------------------------------------------- */

  private resolveSelectionPath(
    event: PointerEvent,
    source: PathSource,
    excludeUtility = true
  ) {
    const hasCoordinates =
      Number.isFinite(event.clientX) && Number.isFinite(event.clientY);

    if (source === "event-path" || !hasCoordinates) {
      return pathFromEventPath(event.composedPath(), excludeUtility);
    }

    // The element at the pointer coordinates.
    const root = this.pre?.getRootNode();

    const scope =
      root instanceof Document || root instanceof ShadowRoot ? root : document;

    const hit = scope.elementFromPoint(event.clientX, event.clientY);

    return hit === null ? null : pathFromElement(hit, excludeUtility);
  }

  private resolveSelectionInfo(
    event: PointerEvent,
    source: PathSource,
    requireNumberColumn: boolean
  ) {
    const path = this.resolveSelectionPath(event, source);

    const target =
      path === null ? null : resolveLineTarget(path, this.isSplit());

    if (
      target === null ||
      (requireNumberColumn && !target.numberColumn) ||
      target.splitLineIndex === undefined
    ) {
      return null;
    }

    return {
      eventSide: target.side,
      lineIndex: target.splitLineIndex,
      lineNumber: target.lineNumber,
    };
  }

  private resolveSelectionPoint(
    event: PointerEvent,
    source: PathSource,
    excludeUtility = true
  ): SelectionPoint | null {
    const path = this.resolveSelectionPath(event, source, excludeUtility);

    const target =
      path === null ? null : resolveLineTarget(path, this.isSplit());

    return target === null
      ? null
      : { lineNumber: target.lineNumber, side: target.side };
  }

  /* ---------------------------------------------------------------- */
  /* Selection range                                                   */
  /* ---------------------------------------------------------------- */

  currentRange() {
    return this.proposedRange === undefined
      ? this.selectedRange
      : this.proposedRange;
  }

  private indexesOf(range: SelectedLineRange, split: boolean) {
    const start = this.options.getLineIndex(
      range.start,
      range.side ?? "additions"
    );

    const end = this.options.getLineIndex(
      range.end,
      range.endSide ?? range.side ?? "additions"
    );

    return start === null || end === null
      ? null
      : { end: split ? end[1] : end[0], start: split ? start[1] : start[0] };
  }

  private updateSelection(
    lineNumber: number | null,
    side: AnnotationSide | undefined,
    notify = true
  ) {
    const previous = this.currentRange();

    const next =
      lineNumber === null
        ? null
        : buildSelectionRange(
            this.anchor?.lineNumber ?? lineNumber,
            lineNumber,
            this.anchor?.side ?? side,
            side
          );

    if (sameRange(previous, next)) {
      return;
    }

    this.highlightSide = undefined;
    this.lineNumberOnly = false;

    if (this.options.controlledSelection) {
      this.proposedRange = next;
    } else {
      this.selectedRange = next;
      this.publish();
    }

    this.placeUtility();

    if (notify) {
      this.options.onLineSelectionChange?.(this.currentRange());
    }
  }

  private clearProposed() {
    this.proposedRange = undefined;
  }

  private notifyStart(range: SelectedLineRange | null) {
    this.options.onLineSelectionStart?.(range);
  }

  private notifyEnd(range: SelectedLineRange | null) {
    this.options.onLineSelectionEnd?.(range);
  }

  private notifyCommitted(range: SelectedLineRange | null) {
    this.options.onLineSelected?.(range);
  }

  /* ---------------------------------------------------------------- */
  /* Starting a selection                                              */
  /* ---------------------------------------------------------------- */

  private startLineSelection(event: PointerEvent) {
    if (!this.options.enableLineSelection) {
      return;
    }

    const info = this.resolveSelectionInfo(event, "event-path", true);

    if (info === null || this.pre === undefined) {
      return;
    }

    const { eventSide, lineIndex, lineNumber } = info;
    const selected = this.selectedRange;

    if (event.shiftKey && selected !== null) {
      const indexes = this.indexesOf(selected, this.isSplit());

      if (indexes === null) {
        return;
      }

      const forward =
        indexes.start <= indexes.end
          ? lineIndex >= indexes.start
          : lineIndex <= indexes.end;

      this.anchor = {
        lineNumber: forward ? selected.start : selected.end,
        side: forward
          ? (selected.side ?? "additions")
          : (selected.endSide ?? selected.side ?? "additions"),
      };
      this.updateSelection(lineNumber, eventSide, false);
      this.notifyStart(this.currentRange());
      this.session = { mode: "selecting", pointerId: event.pointerId };
    } else if (selected?.start === lineNumber && selected.end === lineNumber) {
      const point = { lineNumber, side: eventSide };

      this.anchor = point;
      this.session = {
        anchor: point,
        mode: "pendingSingleLineUnselect",
        pending: point,
        pointerId: event.pointerId,
      };
    } else {
      if (this.options.controlledSelection) {
        this.proposedRange = null;
      } else {
        this.selectedRange = null;
      }

      this.placeUtility();
      this.anchor = { lineNumber, side: eventSide };
      this.updateSelection(lineNumber, eventSide, false);
      this.notifyStart(this.currentRange());
      this.session = { mode: "selecting", pointerId: event.pointerId };
    }

    this.attachDocumentListeners();
  }

  private startGutterSelection(event: PointerEvent) {
    if (this.options.onGutterUtilityClick === undefined) {
      return;
    }

    const ends = this.currentSelectionEnds();

    const bottom =
      ends?.bottom ?? this.resolveSelectionPoint(event, "event-path", false);

    const top = ends?.top ?? bottom;

    if (bottom === null || top === null) {
      return;
    }

    event.preventDefault();
    event.stopPropagation();
    this.session = {
      anchor: top,
      current: bottom,
      mode: "gutterSelecting",
      pointerId: event.pointerId,
    };
    this.anchor = { lineNumber: top.lineNumber, side: top.side };
    this.updateSelection(bottom.lineNumber, bottom.side, false);
    this.notifyStart(this.currentRange());
    this.attachDocumentListeners();
  }

  /* ---------------------------------------------------------------- */
  /* The session                                                       */
  /* ---------------------------------------------------------------- */

  private attachDocumentListeners() {
    if (!this.documentListeners) {
      document.addEventListener("pointermove", this.handleDocumentPointerMove);
      document.addEventListener("pointerup", this.handleDocumentPointerUp);
      document.addEventListener(
        "pointercancel",
        this.handleDocumentPointerCancel
      );
      this.documentListeners = true;
    }
  }

  private detachDocumentListeners() {
    if (this.documentListeners) {
      document.removeEventListener(
        "pointermove",
        this.handleDocumentPointerMove
      );
      document.removeEventListener("pointerup", this.handleDocumentPointerUp);
      document.removeEventListener(
        "pointercancel",
        this.handleDocumentPointerCancel
      );
      this.documentListeners = false;
    }
  }

  private clearSession() {
    this.session = { mode: "idle" };
  }

  private readonly handleDocumentPointerMove = (event: PointerEvent) => {
    const { session } = this;

    if (session.mode === "idle" || event.pointerId !== session.pointerId) {
      return;
    }

    event.preventDefault();

    if (session.mode === "gutterSelecting") {
      const point = this.resolveSelectionPoint(event, "coordinates-first");

      if (point === null) {
        return;
      }

      session.current = point;
      this.updateSelection(point.lineNumber, point.side);

      return;
    }

    const info = this.resolveSelectionInfo(event, "coordinates-first", false);

    if (info === null || this.anchor === undefined) {
      return;
    }

    if (session.mode === "selecting") {
      this.updateSelection(info.lineNumber, info.eventSide);

      return;
    }

    if (
      samePoint(session.pending, {
        lineNumber: info.lineNumber,
        side: info.eventSide,
      })
    ) {
      return;
    }

    this.updateSelection(info.lineNumber, info.eventSide, false);
    this.notifyStart(this.currentRange());
    this.options.onLineSelectionChange?.(this.currentRange());
    this.session = { mode: "selecting", pointerId: event.pointerId };
  };

  private readonly handleDocumentPointerUp = (event: PointerEvent) => {
    const { session } = this;

    if (session.mode === "idle" || event.pointerId !== session.pointerId) {
      return;
    }

    event.preventDefault();

    if (session.mode === "gutterSelecting") {
      const point = this.resolveSelectionPoint(event, "coordinates-first");

      if (point !== null) {
        session.current = point;
        this.updateSelection(point.lineNumber, point.side);
      }

      const range = buildSelectionRange(
        session.anchor.lineNumber,
        session.current.lineNumber,
        session.anchor.side,
        session.current.side
      );

      this.options.onGutterUtilityClick?.({ ...range });
      this.anchor = undefined;
      this.notifyEnd(range);
      this.notifyCommitted(range);
      this.clearProposed();
      this.clearSession();
      this.detachDocumentListeners();

      return;
    }

    if (session.mode === "pendingSingleLineUnselect") {
      this.updateSelection(null, undefined, false);
      this.anchor = undefined;
      this.clearSession();
      this.detachDocumentListeners();
      this.notifyEnd(this.currentRange());
      this.notifyCommitted(this.currentRange());
      this.clearProposed();

      return;
    }

    this.anchor = undefined;
    this.detachDocumentListeners();
    this.clearSession();
    this.notifyEnd(this.currentRange());
    this.notifyCommitted(this.currentRange());
    this.clearProposed();
  };

  private readonly handleDocumentPointerCancel = (event: PointerEvent) => {
    const { session } = this;

    if (session.mode === "idle" || event.pointerId !== session.pointerId) {
      return;
    }

    this.anchor = undefined;
    this.clearProposed();
    this.clearSession();
    this.detachDocumentListeners();
  };

  /* ---------------------------------------------------------------- */
  /* The gutter utility                                                */
  /* ---------------------------------------------------------------- */

  private selectionPointRowIndex(point: SelectionPoint) {
    const indexes = this.options.getLineIndex(point.lineNumber, point.side);

    return indexes === null ? null : indexes[this.isSplit() ? 1 : 0];
  }

  private currentSelectionEnds() {
    const range = this.currentRange();

    if (range === null) {
      return null;
    }

    const first: SelectionPoint = {
      lineNumber: range.start,
      side: range.side ?? "additions",
    };

    const last: SelectionPoint = {
      lineNumber: range.end,
      side: range.endSide ?? range.side ?? "additions",
    };

    const firstRow = this.selectionPointRowIndex(first);
    const lastRow = this.selectionPointRowIndex(last);

    if (firstRow === null || lastRow === null) {
      return null;
    }

    return firstRow > lastRow
      ? { bottom: first, top: last }
      : { bottom: last, top: first };
  }

  /** The number cell of a selection end. */
  private targetForSelectionPoint(point: SelectionPoint): UtilityTarget | null {
    const indexes = this.options.getLineIndex(point.lineNumber, point.side);

    if (this.pre === undefined || indexes === null) {
      return null;
    }

    const cells = this.pre.querySelectorAll(
      `[data-ck-column-number="${point.lineNumber}"][data-line-index="${indexes[0]},${indexes[1]}"]`
    );

    for (const cell of cells) {
      if (cell instanceof HTMLElement) {
        const target = resolveLineTarget(ancestorsOf(cell), this.isSplit());

        if (target?.side === point.side) {
          return {
            column: target.column,
            indexAttribute: target.indexAttribute,
            lineNumber: target.lineNumber,
            side: target.side,
          };
        }
      }
    }

    return null;
  }

  private placeUtilityFromSelection() {
    const ends = this.currentSelectionEnds();

    if (ends === null) {
      return false;
    }

    this.options.onUtilityChange(this.targetForSelectionPoint(ends.bottom));

    return true;
  }

  /** The selection's last line, else the hovered line, else none. */
  placeUtility() {
    if (this.placeUtilityFromSelection()) {
      return;
    }

    this.options.onUtilityChange(this.options.getHovered());
  }

  /** A touch press shows the utility on the pressed number. */
  private revealUtilityFromPath(path: readonly EventTarget[]) {
    if (this.placeUtilityFromSelection()) {
      return;
    }

    const first = path.find((node) => node instanceof Element);

    if (first === undefined) {
      return;
    }

    const cell = pathFromElement(first, false);

    const target =
      cell === null ? null : resolveLineTarget(cell, this.isSplit());

    if (target?.numberColumn === true) {
      this.options.onUtilityChange({
        column: target.column,
        indexAttribute: target.indexAttribute,
        lineNumber: target.lineNumber,
        side: target.side,
      });
    }
  }
}

/* ------------------------------------------------------------------ */
/* Rendering the selection                  */
/* ------------------------------------------------------------------ */

const parseLineIndex = (element: Element, split: boolean) => {
  const indexes = parseIndexes(element.getAttribute("data-line-index") ?? "");

  if (split) {
    return indexes.length === 2 ? indexes[1] : undefined;
  }

  return indexes[0];
};

/**
 * Marks the selected lines with `data-selected-line`: `single`, `first`, `last` or an empty
 * value. The range is a span of row indexes, so in a split diff both columns of a row are
 * marked unless `highlightSide` names one. Unless `lineNumberOnly`, the line bodies and the
 * annotation row under a selected line are marked too.
 */
export const renderSelection = (
  pre: HTMLElement,
  view: SelectionView,
  getLineIndex: LineSelectionOptions["getLineIndex"]
) => {
  for (const marked of pre.querySelectorAll("[data-selected-line]")) {
    marked.removeAttribute("data-selected-line");
  }

  const { range } = view;

  if (range === null) {
    return;
  }

  const split = pre.getAttribute("data-diff-type") === "split";
  const start = getLineIndex(range.start, range.side ?? "additions");

  const end = getLineIndex(
    range.end,
    range.endSide ?? range.side ?? "additions"
  );

  if (start === null || end === null) {
    return;
  }

  const first = Math.min(start[split ? 1 : 0], end[split ? 1 : 0]);
  const last = Math.max(start[split ? 1 : 0], end[split ? 1 : 0]);
  const single = first === last;

  for (const code of pre.children) {
    const column = columnOf(code);

    if (
      view.highlightSide !== undefined &&
      column !== "unified" &&
      view.highlightSide !== column
    ) {
      continue;
    }

    const [gutter, content] = code.children;

    if (!(gutter instanceof HTMLElement && content instanceof HTMLElement)) {
      continue;
    }

    const lines = content.children;
    const numbers = gutter.children;

    for (let index = 0; index < lines.length; index += 1) {
      const line = lines[index];
      const number = numbers[index];

      if (!(line instanceof HTMLElement && number instanceof HTMLElement)) {
        continue;
      }

      const row = parseLineIndex(line, split);

      if ((row ?? 0) > last) {
        break;
      }

      if (row === undefined || row < first || row > last) {
        continue;
      }

      let value = "";

      if (single) {
        value = "single";
      } else if (row === first) {
        value = "first";
      } else if (row === last) {
        value = "last";
      }

      number.setAttribute("data-selected-line", value);

      if (view.lineNumberOnly) {
        continue;
      }

      line.setAttribute("data-selected-line", value);

      const nextLine = lines[index + 1];
      const nextNumber = numbers[index + 1];

      if (
        nextLine instanceof HTMLElement &&
        nextNumber instanceof HTMLElement &&
        nextLine.hasAttribute("data-line-annotation")
      ) {
        let annotation = value;

        if (single) {
          annotation = "last";
          line.setAttribute("data-selected-line", "first");
        } else if (row === first) {
          annotation = "";
        } else if (row === last) {
          line.setAttribute("data-selected-line", "");
        }

        nextLine.setAttribute("data-selected-line", annotation);
        nextNumber.setAttribute("data-selected-line", annotation);
      }
    }
  }
};

/* oxlint-disable eslint/no-bitwise -- ARC4 is defined in bitwise arithmetic; this is the generator of the `seedrandom` package (MIT), used for shimmer widths. */

const WIDTH = 256;
const CHUNKS = 6;
const START_DENOMINATOR = WIDTH ** CHUNKS;
const SIGNIFICANCE = 2 ** 52;
const OVERFLOW = SIGNIFICANCE * 2;
const MASK = WIDTH - 1;

const mixKey = (seed: string) => {
  const key: number[] = [];
  let smear = 0;

  for (let index = 0; index < seed.length; index += 1) {
    smear ^= (key[MASK & index] ?? 0) * 19;
    key[MASK & index] = MASK & (smear + (seed.codePointAt(index) ?? 0));
  }

  return key.length === 0 ? [0] : key;
};

/** seedrandom's default generator: the same seed gives the same sequence in [0, 1). */
export const createSeededRandom = (seed: string) => {
  const key = mixKey(seed);
  const state: number[] = Array.from({ length: WIDTH }, (_, index) => index);
  let i = 0;
  let j = 0;

  for (let index = 0; index < WIDTH; index += 1) {
    const t = state[index];
    j = MASK & (j + key[index % key.length] + t);
    state[index] = state[j];
    state[j] = t;
  }

  const draw = (count: number) => {
    let result = 0;

    for (let step = 0; step < count; step += 1) {
      i = MASK & (i + 1);
      const t = state[i];
      j = MASK & (j + t);
      state[i] = state[j];
      state[j] = t;
      result = result * WIDTH + state[MASK & (state[i] + state[j])];
    }

    return result;
  };

  draw(WIDTH);

  return () => {
    let n = draw(CHUNKS);
    let d = START_DENOMINATOR;
    let x = 0;

    while (n < SIGNIFICANCE) {
      n = (n + x) * WIDTH;
      d *= WIDTH;
      x = draw(1);
    }

    while (n >= OVERFLOW) {
      n /= 2;
      d /= 2;
      x >>>= 1;
    }

    return (n + x) / d;
  };
};

/*
 * Syntax tokenizing for the diff, on Prism through refractor.
 *
 * The app tokenizes in a pool of module workers
 * and colors each token with --diffs-token-light/-dark from the code theme. This
 * file produces the same shape: for each line, the tokens with their offsets,
 * each carrying a token role (the names of the Highlights engine's role
 * table: keyword, string, function, ...). syntax-theme.ts turns a role into the
 * theme colors, so the role is the only thing Prism has to decide.
 */

import css from "refractor/css";
import javascript from "refractor/javascript";
import markup from "refractor/markup";
import python from "refractor/python";
import typescript from "refractor/typescript";

import { GRAMMAR_LOADERS } from "./syntax-grammars";
import { GRAMMAR_BY_LANGUAGE } from "./syntax-languages";
import { refractor } from "./syntax-refractor.js";

/** The languages the app loads before the first file. */
export const PRELOADED_LANGUAGES = [
  "typescript",
  "javascript",
  "css",
  "html",
  "python",
] as const;

// CSS and JavaScript attach embedded grammars only after markup is registered.
for (const grammar of [markup, css, javascript, typescript, python]) {
  refractor.register(grammar);
}

refractor.languages.astro = refractor.languages.extend("markup", {});

refractor.languages.insertBefore("astro", "comment", {
  frontmatter: {
    greedy: true,
    inside: {
      "frontmatter-delimiter": {
        alias: "comment",
        pattern: /^---|(?:---|\.{3})[\t ]*$/u,
      },
      rest: refractor.languages.typescript,
    },
    pattern:
      /^---[\t ]*(?:\r?\n|$)[\s\S]*?(?:\r?\n---|\.{3}[\t ]*(?=\r?\n|$)|$)/u,
  },
});

/** A token of one line: its offset in the line text and its role (none: default color). */
export interface RoleToken {
  content: string;
  offset: number;
  role: string | undefined;
}

export type RoleLines = RoleToken[][];

/**
 * Prism token type to token role. Prism names the syntactic kind of a
 * token; the Highlights engine names the role and the theme colors the role.
 */
const PRISM_TYPE_ROLES = new Map([
  ["atrule", "keyword"],
  ["attr-name", "attribute"],
  ["attr-value", "string"],
  ["boolean", "boolean"],
  ["builtin", "type"],
  ["cdata", "comment"],
  ["char", "string"],
  ["class-name", "type"],
  ["comment", "comment"],
  ["constant", "constant"],
  ["decorator", "attribute"],
  ["doctype", "tag"],
  ["entity", "string.escape"],
  ["function", "function"],
  ["function-variable", "function"],
  ["generic-function", "function"],
  ["important", "keyword"],
  ["keyword", "keyword"],
  ["named-entity", "string.escape"],
  ["number", "number"],
  ["operator", "operator"],
  ["parameter", "variable.parameter"],
  ["prolog", "comment"],
  ["property", "property"],
  ["punctuation", "punctuation"],
  ["regex", "string.regex"],
  ["rule", "keyword"],
  ["selector", "selector"],
  ["string", "string"],
  ["tag", "tag"],
  ["triple-quoted-string", "string"],
  ["url", "link_uri"],
  ["variable", "variable"],
]);

/**
 * Keywords the Highlights engine colors as values, not as keywords: the
 * grammars class them as `keyword` (or `boolean`), the engine as the constant
 * and `this` roles.
 */
const VALUE_KEYWORD_ROLES = new Map([
  ["None", "constant"],
  ["null", "constant"],
  ["self", "variable.special"],
  ["super", "variable.special"],
  ["this", "variable.special"],
  ["undefined", "constant"],
]);

const roleOfClasses = (
  classes: readonly string[],
  inherited: string | undefined
) => {
  let role = inherited;

  for (const name of classes) {
    const named = PRISM_TYPE_ROLES.get(name);

    // The quotes of a string are string-colored; they are not punctuation.
    if (
      named !== undefined &&
      !(name === "punctuation" && inherited === "string")
    ) {
      role = named;
    }
  }

  return role;
};

/**
 * Grammars whose plain identifiers the engine colors as variables. Prism leaves
 * an identifier without a class; the engine's role table has `variable` for it.
 * Checked against the engine for these grammars only (see the round 3 report).
 */
const IDENTIFIER_VARIABLE_GRAMMARS = new Set([
  "javascript",
  "jsx",
  "python",
  "tsx",
  "typescript",
]);

const IDENTIFIER = /[A-Za-z_$][\w$]*/gu;

interface HastNode {
  children?: HastNode[];
  properties?: { className?: string[] };
  type: string;
  value?: string;
}

const grammarFile = (language: string) => GRAMMAR_BY_LANGUAGE.get(language);

/** Languages a file can be tokenized in right away, without a download. */
export const isLanguageLoaded = (language: string) => {
  const file = grammarFile(language);

  return file !== undefined && refractor.registered(file);
};

/** Load the grammar of a language. Resolves false when Prism has none. */
export const loadLanguage = async (language: string) => {
  const file = grammarFile(language);

  if (file === undefined) {
    return false;
  }

  if (!refractor.registered(file)) {
    const loader = GRAMMAR_LOADERS.get(file);

    if (loader === undefined) {
      return false;
    }

    const grammar = await loader();
    refractor.register(grammar.default);
  }

  return true;
};

const roleOfText = (text: string, role: string | undefined) =>
  role === undefined ? role : (VALUE_KEYWORD_ROLES.get(text) ?? role);

const pushToken = (
  tokens: RoleToken[],
  content: string,
  offset: number,
  role: string | undefined
) => {
  const previous = tokens.at(-1);

  if (previous && previous.role === role) {
    previous.content += content;
  } else {
    tokens.push({ content, offset, role });
  }
};

const pushIdentifiers = (tokens: RoleToken[], text: string, offset: number) => {
  let position = 0;

  for (const match of text.matchAll(IDENTIFIER)) {
    if (match.index > position) {
      pushToken(
        tokens,
        text.slice(position, match.index),
        offset + position,
        undefined
      );
    }

    pushToken(tokens, match[0], offset + match.index, "variable");
    position = match.index + match[0].length;
  }

  if (position < text.length) {
    pushToken(tokens, text.slice(position), offset + position, undefined);
  }
};

const collect = (
  node: HastNode,
  inherited: string | undefined,
  lines: RoleLines,
  state: { identifiers: boolean; line: number; offset: number }
) => {
  if (node.type === "text") {
    const parts = (node.value ?? "").split("\n");

    for (const [index, part] of parts.entries()) {
      if (index > 0) {
        state.line += 1;
        state.offset = 0;
        lines[state.line] ??= [];
      }

      if (part === "") {
        continue;
      }

      lines[state.line] ??= [];
      const tokens = lines[state.line] ?? [];

      if (inherited === undefined && state.identifiers) {
        pushIdentifiers(tokens, part, state.offset);
      } else {
        pushToken(tokens, part, state.offset, roleOfText(part, inherited));
      }

      state.offset += part.length;
    }

    return;
  }

  const classes = node.properties?.className ?? [];

  const role =
    node.type === "element" ? roleOfClasses(classes, inherited) : inherited;

  for (const child of node.children ?? []) {
    collect(child, role, lines, state);
  }
};

/**
 * Tokenize a document in a language into lines of role tokens. A line at or
 * over `tokenizeMaxLineLength` becomes one default token, and is kept out of Prism so a minified
 * line cannot stall the tokenizer.
 */
export const tokenizeRoles = (
  contents: string,
  language: string,
  tokenizeMaxLineLength: number
): RoleLines | undefined => {
  const file = grammarFile(language);

  if (file === undefined || !refractor.registered(file)) {
    return undefined;
  }

  const source = contents.split("\n");
  const longLines = new Set<number>();

  const prepared = source.map((line, index) => {
    const text = line.endsWith("\r") ? line.slice(0, -1) : line;

    if (tokenizeMaxLineLength > 0 && text.length >= tokenizeMaxLineLength) {
      longLines.add(index);

      return "";
    }

    return text;
  });

  const lines: RoleLines = [];

  const state = {
    identifiers: IDENTIFIER_VARIABLE_GRAMMARS.has(file),
    line: 0,
    offset: 0,
  };

  lines[0] = [];
  collect(
    refractor.highlight(prepared.join("\n"), file),
    undefined,
    lines,
    state
  );

  for (const index of longLines) {
    const text = source[index] ?? "";
    const length = text.endsWith("\r") ? text.length - 1 : text.length;
    lines[index] = [
      { content: text.slice(0, length), offset: 0, role: undefined },
    ];
  }

  while (lines.length < source.length) {
    lines.push([]);
  }

  return lines;
};

/* oxlint-disable shadcn/no-inline-styles -- the app sets each token's --diffs-token-light/-dark inline; the values come from the code theme, not from this project's tokens. */

/*
 * The DOM of a highlighted diff line.
 *
 * A token with outer whitespace splits into the whitespace and the trimmed
 * token. A token is a span with its --diffs-token-light/-dark style and its
 * offset in `data-char`. The word diff ranges cut the tokens into pieces and
 * wrap them, and pieces of one token regroup under a span that carries the
 * offset.
 */

import type { CSSProperties, ReactElement } from "react";

import { DEFAULT_SYNTAX_THEMES } from "./code-themes";
import type { RoleToken } from "./syntax-highlight";
import { resolveRoleStyle } from "./syntax-theme";
import type { SyntaxThemes, ZedTheme } from "./syntax-theme";

const styleCache = new Map<string, CSSProperties>();

const themeStyle = (theme: ZedTheme, role: string | undefined) => {
  const fallback = theme.style["editor.foreground"];

  if (role === undefined) {
    return { color: fallback, italic: false, weight: 0 };
  }

  const resolved = resolveRoleStyle(theme, role);

  return { ...resolved, color: resolved.color ?? fallback };
};

/**
 * The token style: `--diffs-token-light` and `--diffs-token-dark`
 * (the engine's `htmlStyle` with `defaultColor: false` and the `token`
 * prefix). The developer themes agree on italic and weight, so those are plain
 * declarations; the engine writes a theme-less declaration in that case too.
 */
export const tokenStyle = (
  role: string | undefined,
  themes: SyntaxThemes = DEFAULT_SYNTAX_THEMES
): CSSProperties => {
  const key = `${themes.light.name}\u0000${themes.dark.name}\u0000${role ?? ""}`;
  const cached = styleCache.get(key);

  if (cached !== undefined) {
    return cached;
  }

  const light = themeStyle(themes.light, role);
  const dark = themeStyle(themes.dark, role);

  const entries: [string, number | string][] = [
    ["--diffs-token-dark", dark.color],
    ["--diffs-token-light", light.color],
  ];

  if (light.italic && dark.italic) {
    entries.push(["fontStyle", "italic"]);
  } else if (light.italic) {
    entries.push(["--diffs-token-light-font-style", "italic"]);
  } else if (dark.italic) {
    entries.push(["--diffs-token-dark-font-style", "italic"]);
  }

  if (light.weight !== 0 && light.weight === dark.weight) {
    entries.push(["fontWeight", light.weight]);
  } else {
    if (light.weight !== 0) {
      entries.push(["--diffs-token-light-font-weight", light.weight]);
    }

    if (dark.weight !== 0) {
      entries.push(["--diffs-token-dark-font-weight", dark.weight]);
    }
  }

  // SAFETY: CSSProperties has no keys for custom properties; React sets every
  // key of the style object, custom properties included, with setProperty.
  const style = Object.fromEntries(entries) as CSSProperties;
  styleCache.set(key, style);

  return style;
};

/** A span of the line: a token piece (text) or a word diff wrapper (children). */
interface LineNode {
  children: LineNode[];
  dataChar: number | undefined;
  diffSpan: boolean;
  style: CSSProperties | undefined;
  text: string | undefined;
}

export interface LineRange {
  length: number;
  start: number;
}

interface Piece {
  content: string;
  offset: number;
  style: CSSProperties | undefined;
}

/** Split a token around its outer whitespace. */
const splitTokens = (
  tokens: readonly RoleToken[],
  themes: SyntaxThemes
): Piece[] =>
  tokens.flatMap((token) => {
    const style = tokenStyle(token.role, themes);
    const trimmed = token.content.trim();

    if (trimmed === "" || trimmed === token.content) {
      return [{ content: token.content, offset: token.offset, style }];
    }

    const lead = token.content.indexOf(trimmed);
    const end = lead + trimmed.length;

    return [
      {
        content: token.content.slice(0, lead),
        offset: token.offset,
        style: undefined,
      },
      { content: trimmed, offset: token.offset + lead, style },
      {
        content: token.content.slice(end),
        offset: token.offset + end,
        style: undefined,
      },
    ];
  });

const tokenNode = (
  content: string,
  offset: number,
  style: CSSProperties | undefined
): LineNode => ({
  children: [],
  dataChar: offset,
  diffSpan: false,
  style,
  text: content,
});

/** One span per token. */
const plainNodes = (pieces: readonly Piece[]) =>
  pieces.flatMap((piece) =>
    piece.content === ""
      ? []
      : [tokenNode(piece.content, piece.offset, piece.style)]
  );

const rangeAt = (ranges: readonly LineRange[], index: number) =>
  ranges.find(
    (range) =>
      range.length > 0 &&
      index >= range.start &&
      index < range.start + range.length
  );

/** The next position after `position` where a range starts, up to `limit`. */
const nextEdge = (
  ranges: readonly LineRange[],
  position: number,
  limit: number
) => {
  let edge = limit;

  for (const range of ranges) {
    if (range.length > 0 && range.start > position && range.start < edge) {
      edge = range.start;
    }
  }

  return edge;
};

/** Cut the tokens at the range edges and wrap the pieces inside a range. */
const decoratedNodes = (
  pieces: readonly Piece[],
  ranges: readonly LineRange[]
): LineNode[] => {
  const root: LineNode[] = [];
  let wrapper: LineNode | undefined;
  let wrapperRange: LineRange | undefined;

  for (const piece of pieces) {
    const tokenStart = piece.offset;
    const tokenEnd = tokenStart + piece.content.length;
    let position = tokenStart;

    while (position < tokenEnd) {
      const range = rangeAt(ranges, position);

      const end = range
        ? Math.min(tokenEnd, range.start + range.length)
        : nextEdge(ranges, position, tokenEnd);

      const node = tokenNode(
        piece.content.slice(position - tokenStart, end - tokenStart),
        tokenStart,
        piece.style
      );

      if (range === undefined) {
        wrapper = undefined;
        wrapperRange = undefined;
        root.push(node);
      } else {
        if (wrapper === undefined || wrapperRange !== range) {
          wrapper = {
            children: [],
            dataChar: undefined,
            diffSpan: true,
            style: undefined,
            text: undefined,
          };
          wrapperRange = range;
          root.push(wrapper);
        }

        wrapper.children.push(node);
      }

      position = end;
    }
  }

  return root;
};

/** Offsets are not negative, so these two never collide with a token offset. */
const NO_TOKEN = -1;
const MULTIPLE_TOKENS = -2;

const clearDataChar = (node: LineNode) => {
  node.dataChar = undefined;

  for (const child of node.children) {
    clearDataChar(child);
  }
};

/** What a child adds to the token a parent holds. */
const mergeToken = (held: number, found: number) => {
  if (found === NO_TOKEN) {
    return held;
  }

  if (found === MULTIPLE_TOKENS || (held !== NO_TOKEN && held !== found)) {
    return MULTIPLE_TOKENS;
  }

  return found;
};

/** A run of pieces of one token as one node: the piece itself, or a span around several. */
const groupNode = (group: readonly LineNode[], offset: number): LineNode => {
  const [only] = group;

  if (group.length === 1 && only !== undefined) {
    for (const child of only.children) {
      clearDataChar(child);
    }

    only.dataChar = offset;

    return only;
  }

  for (const member of group) {
    clearDataChar(member);
  }

  return {
    children: [...group],
    dataChar: offset,
    diffSpan: false,
    style: undefined,
    text: undefined,
  };
};

/** Regroup the pieces of one token under a span that carries its offset. */
const regroup = (node: LineNode): number => {
  if (node.dataChar !== undefined) {
    return node.dataChar;
  }

  let held = NO_TOKEN;
  const output: LineNode[] = [];
  let group: LineNode[] = [];
  let groupChar = NO_TOKEN;

  const flush = () => {
    if (group.length > 0 && groupChar >= 0) {
      output.push(groupNode(group, groupChar));
    }

    group = [];
    groupChar = NO_TOKEN;
  };

  for (const child of node.children) {
    const found = regroup(child);
    held = mergeToken(held, found);

    if (found >= 0) {
      if (groupChar >= 0 && groupChar !== found) {
        flush();
      }

      groupChar = found;
      group.push(child);
    } else {
      flush();
      output.push(child);
    }
  }

  flush();
  node.children = output;

  return held;
};

const toElement = (node: LineNode, key: number): ReactElement => (
  <span
    data-char={node.dataChar}
    data-diff-span={node.diffSpan ? "" : undefined}
    key={key}
    style={node.style}
  >
    {node.text ?? node.children.map((child, index) => toElement(child, index))}
  </span>
);

/**
 * The children of a highlighted `[data-line]`. Returns undefined when the
 * tokens do not spell the line text, so the caller shows the plain line.
 */
export const renderTokenLine = (
  text: string,
  tokens: readonly RoleToken[],
  ranges: readonly LineRange[] | undefined,
  themes: SyntaxThemes = DEFAULT_SYNTAX_THEMES
): ReactElement[] | undefined => {
  if (tokens.map((token) => token.content).join("") !== text) {
    return undefined;
  }

  const pieces = splitTokens(tokens, themes);

  if (ranges === undefined || ranges.length === 0) {
    return plainNodes(pieces).map((node, index) => toElement(node, index));
  }

  const line: LineNode = {
    children: decoratedNodes(
      pieces.filter((piece) => piece.content !== ""),
      ranges
    ),
    dataChar: undefined,
    diffSpan: false,
    style: undefined,
    text: undefined,
  };

  regroup(line);

  return line.children.map((node, index) => toElement(node, index));
};

/* The diff's four-worker tokenizer pool and 100-entry result cache. */

import type { RoleLines } from "./syntax-highlight";
import type { TokenizeRequest, TokenizeResponse } from "./syntax-worker";

const POOL_SIZE = 4;
const CACHE_SIZE = 100;

interface Pending {
  reject: (error: Error) => void;
  request: TokenizeRequest;
  resolve: (lines: RoleLines | null) => void;
}

interface Slot {
  listeners: AbortController;
  pending?: Pending;
  worker: Worker;
}

const queue: Pending[] = [];
const cache = new Map<string, RoleLines | null>();
let slots: Slot[] = [];
let nextId = 0;

const remember = (key: string, lines: RoleLines | null) => {
  cache.delete(key);
  cache.set(key, lines);

  if (cache.size > CACHE_SIZE) {
    const oldest = cache.keys().next().value;

    if (oldest !== undefined) {
      cache.delete(oldest);
    }
  }
};

const failPool = (error: Error) => {
  for (const slot of slots) {
    slot.listeners.abort();
    slot.worker.terminate();
    slot.pending?.reject(error);
  }

  slots = [];

  for (const pending of queue.splice(0)) {
    pending.reject(error);
  }
};

const pump = () => {
  for (const slot of slots) {
    if (slot.pending) {
      continue;
    }

    const pending = queue.shift();

    if (!pending) {
      break;
    }

    slot.pending = pending;

    try {
      // oxlint-disable-next-line unicorn/require-post-message-target-origin -- Worker.postMessage takes no target origin.
      slot.worker.postMessage(pending.request);
    } catch (error) {
      failPool(error instanceof Error ? error : new Error(String(error)));

      return;
    }
  }
};

const createPool = () => {
  try {
    for (let index = 0; index < POOL_SIZE; index += 1) {
      const worker = new Worker(
        // oxlint-disable-next-line unicorn/relative-url-style -- Bundlers require a relative module path.
        new URL("./syntax-worker.ts", import.meta.url),
        {
          type: "module",
        }
      );

      const listeners = new AbortController();
      const slot: Slot = { listeners, worker };
      slots.push(slot);
      worker.addEventListener(
        "message",
        (event: MessageEvent<TokenizeResponse>) => {
          const { pending } = slot;

          if (!pending || event.data.id !== pending.request.id) {
            failPool(new Error("Unexpected tokenizer worker response"));

            return;
          }

          slot.pending = undefined;

          if (event.data.error === undefined) {
            pending.resolve(event.data.lines);
          } else {
            pending.reject(new Error(event.data.error));
          }

          pump();
        },
        { signal: listeners.signal }
      );

      worker.addEventListener(
        "error",
        (event) => {
          failPool(new Error(event.message || "Tokenizer worker failed"));
        },
        { signal: listeners.signal }
      );

      worker.addEventListener(
        "messageerror",
        () => {
          failPool(new Error("Tokenizer worker message could not be read"));
        },
        { signal: listeners.signal }
      );
    }
  } catch (error) {
    failPool(error instanceof Error ? error : new Error(String(error)));
  }
};

/** The role lines of a document, or null when Prism has no grammar for the language. */
export const requestRoleLines = async (
  contents: string,
  language: string,
  tokenizeMaxLineLength: number
): Promise<RoleLines | null> => {
  const key = `${language}\u0000${tokenizeMaxLineLength}\u0000${contents}`;
  const cached = cache.get(key);

  if (cached !== undefined) {
    remember(key, cached);

    return cached;
  }

  nextId += 1;

  // oxlint-disable-next-line promise/avoid-new -- Workers answer requests asynchronously.
  return await new Promise((resolve, reject) => {
    queue.push({
      reject,
      request: { contents, id: nextId, language, tokenizeMaxLineLength },
      resolve: (lines) => {
        remember(key, lines);
        resolve(lines);
      },
    });

    if (slots.length === 0) {
      createPool();
    }

    pump();
  });
};

/*
 * Code theme resolution for the diff's syntax highlighting.
 *
 * Code themes are TextMate themes, converted to the Zed form the highlighter
 * reads. A token role then resolves to a color, an italic flag and a weight.
 * This file holds the conversion and the resolution for every theme,
 * including Developer Light and Developer Dark.
 */

export interface TextMateTokenColor {
  name?: string;
  scope?: string | string[];
  settings: {
    "-webkit-font-smoothing"?: string;
    background?: string;
    content?: string;
    fontStyle?: string;
    foreground?: string;
    "text-decoration"?: string;
  };
}

export interface TextMateTheme {
  bg?: string;
  colors?: {
    [key: string]: string | string[] | null | undefined;
    "editor.background"?: string;
    "editor.foreground"?: string;
  };
  fg?: string;
  name: string;
  semanticTokenColors?: Record<string, string>;
  settings?: TextMateTokenColor[];
  tokenColors?: TextMateTokenColor[];
  type?: "dark" | "light";
}

export interface ZedSyntaxStyle {
  color?: string;
  font_style?: "italic" | "normal";
  font_weight?: number;
}

export interface ZedTheme {
  appearance: "dark" | "light";
  name: string;
  style: {
    "editor.background": string;
    "editor.foreground": string;
    syntax: Record<string, ZedSyntaxStyle>;
  };
}

export interface SyntaxThemes {
  dark: ZedTheme;
  light: ZedTheme;
}

/** The Zed token roles and the TextMate scopes they take their style from. */
const ZED_ROLE_SCOPES = {
  attribute: ["entity.other.attribute-name"],
  boolean: ["constant.language.boolean", "constant.language"],
  comment: ["comment"],
  constant: ["constant"],
  constructor: ["entity.name.type.class"],
  "diff.minus": ["markup.deleted"],
  "diff.plus": ["markup.inserted"],
  emphasis: ["markup.italic"],
  "emphasis.strong": ["markup.bold"],
  function: ["entity.name.function", "support.function"],
  keyword: ["keyword", "storage.type", "storage.modifier"],
  link_text: ["markup.underline.link"],
  link_uri: ["markup.underline.link", "string.other.link"],
  number: ["constant.numeric"],
  operator: ["keyword.operator"],
  preproc: ["keyword.control.directive"],
  property: ["variable.other.property", "support.type.property-name"],
  "property.json_key": ["support.type.property-name.json"],
  punctuation: ["punctuation"],
  string: ["string"],
  "string.escape": ["constant.character.escape"],
  "string.regex": ["string.regexp"],
  tag: ["entity.name.tag"],
  "text.literal": ["markup.inline.raw"],
  title: ["markup.heading"],
  type: ["entity.name.type", "support.type"],
  variable: ["variable"],
  "variable.parameter": ["variable.parameter"],
  "variable.special": ["variable.language"],
} satisfies Record<string, string[]>;

const scopesOfRule = (rule: TextMateTokenColor) =>
  [rule.scope ?? []].flat().flatMap((scope) => scope.split(","));

/**
 * The style a role takes from the rules: of the rules whose scope is, or is a
 * parent of, one of the role's scopes, the longest scope wins, separately for
 * the color and for the font.
 */
const styleOfRole = (
  rules: readonly TextMateTokenColor[],
  roleScopes: readonly string[]
): ZedSyntaxStyle => {
  const style: ZedSyntaxStyle = {};
  let colorLength = -1;
  let fontLength = -1;

  for (const rule of rules) {
    const { fontStyle, foreground } = rule.settings;

    for (const raw of scopesOfRule(rule)) {
      const scope = raw.trim();

      const matches =
        scope !== "" &&
        roleScopes.some(
          (entry) => entry === scope || entry.startsWith(`${scope}.`)
        );

      if (matches && foreground !== undefined && scope.length >= colorLength) {
        style.color = foreground;
        colorLength = scope.length;
      }

      if (matches && fontStyle !== undefined && scope.length >= fontLength) {
        style.font_style = fontStyle.includes("italic") ? "italic" : "normal";
        style.font_weight = fontStyle.includes("bold") ? 700 : 400;
        fontLength = scope.length;
      }
    }
  }

  return style;
};

/** TextMate theme to Zed theme. */
export const toZedTheme = (theme: TextMateTheme): ZedTheme => {
  const rules = theme.tokenColors ?? theme.settings ?? [];
  const base = rules.find((rule) => rule.scope === undefined);
  const appearance = theme.type === "light" ? "light" : "dark";
  const syntax: Record<string, ZedSyntaxStyle> = {};

  for (const [role, scopes] of Object.entries(ZED_ROLE_SCOPES)) {
    syntax[role] = styleOfRole(rules, scopes);
  }

  return {
    appearance,
    name: theme.name,
    style: {
      "editor.background":
        theme.bg ??
        theme.colors?.["editor.background"] ??
        base?.settings.background ??
        "var(--color-code-surface)",
      "editor.foreground":
        theme.fg ??
        theme.colors?.["editor.foreground"] ??
        base?.settings.foreground ??
        "var(--color-syntax-comment)",
      syntax,
    },
  };
};

export interface ResolvedTokenStyle {
  color: string | undefined;
  italic: boolean;
  weight: number;
}

const HEX_COLOR = /^#(?:[a-f0-9]{3,4}|[a-f0-9]{6}|[a-f0-9]{8})$/iu;

/** The style of a role, falling back through its dotted parents. */
const lookupRole = (
  syntax: Record<string, ZedSyntaxStyle>,
  role: string
): ZedSyntaxStyle | undefined => {
  let first: ZedSyntaxStyle | undefined;

  for (let name = role; name !== "";) {
    const entry = Object.hasOwn(syntax, name) ? syntax[name] : undefined;

    if (entry !== undefined) {
      first ??= entry;

      if (entry.color !== undefined) {
        return { ...first, color: entry.color };
      }
    }

    const dot = name.lastIndexOf(".");
    name = dot === -1 ? "" : name.slice(0, dot);
  }

  return first;
};

const canonicalHex = (color: string) => {
  let value = color.trim().toLowerCase();

  if (value.length <= 5) {
    value = value.replaceAll(/[^#]/gu, "$&$&");
  }

  return value.length === 9 && value.endsWith("ff") ? value.slice(0, 7) : value;
};

const normalizeColor = (color: string | undefined) => {
  const value =
    color !== undefined && HEX_COLOR.test(color.trim())
      ? canonicalHex(color)
      : undefined;

  return value === `#${"0".repeat(8)}` ? undefined : value;
};

/** Color, italic and weight of a role in a Zed theme. */
export const resolveRoleStyle = (
  theme: ZedTheme,
  role: string
): ResolvedTokenStyle => {
  const found = lookupRole(theme.style.syntax, role);

  const hasFont =
    found?.font_style !== undefined || found?.font_weight !== undefined;

  const color = hasFont
    ? (found?.color ?? theme.style["editor.foreground"])
    : found?.color;

  const weight = found?.font_weight ?? 0;

  return {
    color: normalizeColor(color),
    italic: found?.font_style === "italic",
    weight: weight >= 100 && weight <= 900 ? Math.round(weight / 100) * 100 : 0,
  };
};

/*
 * The tokenizer worker. It runs in a module worker, loads the Prism grammar a request names,
 * tokenizes the document and posts the role lines back.
 */

import { loadLanguage, tokenizeRoles } from "./syntax-highlight";
import type { RoleLines } from "./syntax-highlight";

export interface TokenizeRequest {
  contents: string;
  id: number;
  language: string;
  tokenizeMaxLineLength: number;
}

export interface TokenizeResponse {
  error?: string;
  id: number;
  lines: RoleLines | null;
}

const handle = async ({
  contents,
  id,
  language,
  tokenizeMaxLineLength,
}: TokenizeRequest) => {
  const response: TokenizeResponse = { id, lines: null };

  try {
    if (await loadLanguage(language)) {
      response.lines =
        tokenizeRoles(contents, language, tokenizeMaxLineLength) ?? null;
    }
  } catch (error) {
    response.error = error instanceof Error ? error.message : String(error);
  }

  // oxlint-disable-next-line unicorn/require-post-message-target-origin -- Worker scope postMessage takes no target origin.
  self.postMessage(response);
};

self.addEventListener("message", (event: MessageEvent<TokenizeRequest>) => {
  handle(event.data).catch(console.error);
});

