"use client";

import { useEffect, useState } from "react";

import {
  DEFAULT_CODE_THEME_SELECTION,
  DEFAULT_SYNTAX_THEMES,
  loadCodeThemes,
} from "./code-themes";
import type { CodeThemeSelection } from "./code-themes";
import type { SyntaxThemes } from "./syntax-theme";

/** Resolve the selected themes on demand, with the default theme as the pending state. */
export const useCodeThemes = (
  selection: CodeThemeSelection = DEFAULT_CODE_THEME_SELECTION
): SyntaxThemes => {
  const key = `${selection.light}\u0000${selection.dark}`;
  const { light } = selection;
  const { dark } = selection;

  const [resolved, setResolved] = useState<{
    key: string;
    themes: SyntaxThemes;
  }>({ key, themes: DEFAULT_SYNTAX_THEMES });

  useEffect(() => {
    let cancelled = false;

    if (
      key !==
      `${DEFAULT_CODE_THEME_SELECTION.light}\u0000${DEFAULT_CODE_THEME_SELECTION.dark}`
    ) {
      loadCodeThemes({ dark, light })
        .then((themes) => {
          if (!cancelled) {
            setResolved({ key, themes });
          }

          return themes;
        })
        .catch(console.error);
    }

    return () => {
      cancelled = true;
    };
  }, [dark, key, light]);

  return resolved.key === key ? resolved.themes : DEFAULT_SYNTAX_THEMES;
};

"use client";

import { useCallback, useRef, useState } from "react";

export type DiffContextStatus = "error" | "idle" | "loading";

const CONTEXT_LOADING_DELAY_MS = 500;

/**
 * Wraps the context loader.
 * The status turns "loading" when a load takes longer than 500ms and stays
 * "error" after a failure until the next load starts.
 */
export const useDiffContextLoader = <Args extends unknown[], Result>(
  load: ((...args: Args) => Promise<Result>) | undefined
) => {
  const [status, setStatus] = useState<DiffContextStatus>("idle");
  const generation = useRef(0);

  const track = useCallback(
    async (...args: Args): Promise<Result> => {
      if (load === undefined) {
        throw new Error(
          "Diff context loading needs a loader before tracking can begin"
        );
      }

      generation.current += 1;
      const mine = generation.current;

      const update = (next: DiffContextStatus) => {
        if (mine === generation.current) {
          setStatus(next);
        }
      };

      update("idle");

      const timer = setTimeout(() => {
        update("loading");
      }, CONTEXT_LOADING_DELAY_MS);

      try {
        const result = await load(...args);

        clearTimeout(timer);
        update("idle");

        return result;
      } catch (error) {
        clearTimeout(timer);
        update("error");
        throw error;
      }
    },
    [load]
  );

  return { status, track };
};

"use client";

/*
 * The tokens of a diff, as the app's worker pool delivers them: a diff renders
 * as plain text first (the pending state), and the lines are replaced by their
 * tokens when the pool answers.
 *
 * The component tokenizes each side of the diff as one document.
 * A complete diff is two documents, the whole old file and the whole new file.
 * A partial diff is one document per hunk and side, because only those lines
 * are known. The old side is tokenized in the language of the old file name
 * and a diff whose both sides have no language stays plain. A
 * diff of more than `tokenizeMaxLength` lines on a side stays plain.
 */

import { useEffect, useState } from "react";

import type { FileDiffMetadata } from "./diff-model";
import type { RoleToken } from "./syntax-highlight";
import { languageForFileName } from "./syntax-languages";
import { requestRoleLines } from "./syntax-pool";

/** Library default `tokenizeMaxLineLength`. */
export const TOKENIZE_MAX_LINE_LENGTH = 1000;

/** Library default `tokenizeMaxLength`. */
export const TOKENIZE_MAX_LENGTH = 100_000;

export interface DiffTokens {
  additions: readonly (readonly RoleToken[] | undefined)[];
  deletions: readonly (readonly RoleToken[] | undefined)[];
}

interface MutableDiffTokens {
  additions: (readonly RoleToken[] | undefined)[];
  deletions: (readonly RoleToken[] | undefined)[];
}

export interface DiffTokenOptions {
  tokenizeMaxLength?: number;
  tokenizeMaxLineLength?: number;
}

interface Segment {
  language: string;
  lines: readonly string[];
  side: keyof DiffTokens;
  start: number;
}

const isPlainDiff = (diff: FileDiffMetadata) => {
  const language = diff.lang ?? languageForFileName(diff.name);

  const previous =
    diff.lang ??
    (diff.prevName === undefined ? "text" : languageForFileName(diff.prevName));

  return language === "text" && previous === "text";
};

const segmentsOf = (diff: FileDiffMetadata): Segment[] => {
  const additionLanguage = diff.lang ?? languageForFileName(diff.name);

  const deletionLanguage =
    diff.lang ?? languageForFileName(diff.prevName ?? diff.name);

  if (!diff.isPartial) {
    return [
      {
        language: deletionLanguage,
        lines: diff.deletionLines,
        side: "deletions",
        start: 0,
      },
      {
        language: additionLanguage,
        lines: diff.additionLines,
        side: "additions",
        start: 0,
      },
    ];
  }

  return diff.hunks.flatMap((hunk) => [
    {
      language: deletionLanguage,
      lines: diff.deletionLines.slice(
        hunk.deletionLineIndex,
        hunk.deletionLineIndex + hunk.deletionCount
      ),
      side: "deletions" as const,
      start: hunk.deletionLineIndex,
    },
    {
      language: additionLanguage,
      lines: diff.additionLines.slice(
        hunk.additionLineIndex,
        hunk.additionLineIndex + hunk.additionCount
      ),
      side: "additions" as const,
      start: hunk.additionLineIndex,
    },
  ]);
};

/** The tokens of a diff, or undefined while they are pending or when the diff stays plain. */
export const useDiffTokens = (
  diff: FileDiffMetadata,
  {
    tokenizeMaxLength = TOKENIZE_MAX_LENGTH,
    tokenizeMaxLineLength = TOKENIZE_MAX_LINE_LENGTH,
  }: DiffTokenOptions = {}
) => {
  const [result, setResult] = useState<{
    diff: FileDiffMetadata;
    tokens: DiffTokens;
  } | null>(null);

  useEffect(() => {
    let cancelled = false;

    const plain =
      Math.max(diff.additionLines.length, diff.deletionLines.length) >
        tokenizeMaxLength || isPlainDiff(diff);

    const load = async () => {
      const tokens: MutableDiffTokens = { additions: [], deletions: [] };

      try {
        await Promise.all(
          segmentsOf(diff).map(async (segment) => {
            if (segment.lines.length === 0) {
              return;
            }

            const lines = await requestRoleLines(
              segment.lines.join(""),
              segment.language,
              tokenizeMaxLineLength
            );

            for (const [index, line] of (lines ?? []).entries()) {
              if (index < segment.lines.length) {
                tokens[segment.side][segment.start + index] = line;
              }
            }
          })
        );

        if (!cancelled) {
          setResult({ diff, tokens });
        }
      } catch (error) {
        // The app logs a highlight error and keeps the plain lines (`onHighlightError`).
        console.error(error);
      }
    };

    if (!plain) {
      load().catch(console.error);
    }

    return () => {
      cancelled = true;
    };
  }, [diff, tokenizeMaxLength, tokenizeMaxLineLength]);

  return result !== null && result.diff === diff ? result.tokens : undefined;
};

"use client";

import { useCallback, useEffect } from "react";

const TOGGLE_ALL_EVENT = "toggle-all-diffs";

interface ToggleDetail {
  open: boolean;
  scope: string | undefined;
}

const isToggleEvent = (event: Event): event is CustomEvent<ToggleDetail> =>
  event instanceof CustomEvent;

/**
 * Alt-clicking a file header toggles every diff
 * in the same scope through a window event.
 */
export const useToggleAllDiffs = (
  onOpenChange: (open: boolean) => void,
  scope?: string
) => {
  useEffect(() => {
    const listener = (event: Event) => {
      if (!isToggleEvent(event)) {
        return;
      }

      const { open, scope: eventScope } = event.detail;

      if (scope !== undefined && scope !== "" && eventScope !== scope) {
        return;
      }

      if (
        (scope !== undefined && scope !== "") ||
        eventScope === undefined ||
        eventScope === ""
      ) {
        onOpenChange(open);
      }
    };

    window.addEventListener(TOGGLE_ALL_EVENT, listener);

    return () => {
      window.removeEventListener(TOGGLE_ALL_EVENT, listener);
    };
  }, [onOpenChange, scope]);

  return useCallback(
    (open: boolean) => {
      window.dispatchEvent(
        new CustomEvent<ToggleDetail>(TOGGLE_ALL_EVENT, {
          detail: { open, scope },
        })
      );
    },
    [scope]
  );
};

/*
 * Diff view styles. The app renders diffs with @pierre/diffs inside a shadow
 * root (<diffs-container>); this project cannot depend on that package, so the
 * library stylesheet is reproduced here
 * (its "base" layer), scoped under .root in place of
 * :host. The app's own overrides follow it, and the root-level --diffs-* values come from
 * (":root{--diffs-font-family:var(--font-mono);...}").
 */

/*
 * themeType "system": the library follows the OS preference. The default
 * follows the nearest theme scope, so the library's `color-scheme: light dark`
 * on :host is not applied to .root itself; the build lowers that declaration
 * to toggles that follow the OS and would override the scope's.
 */
.system {
  color-scheme: light dark;
}

/*
 * :root defaults. They sit in the components layer so a
 * consumer's utility class (the component sets [--diffs-font-size:13px] on its
 * diff) overrides them; unlayered rules always win over layered utilities.
 */
