  .root {
    --diffs-font-family: var(--font-mono);
    --diffs-font-size: var(--ck-type-code-size, 12px);
    --diffs-line-height: calc(var(--diffs-font-size, 12px) * 1.8);
    --diffs-deletion-color-override: var(--ck-palette-decoration-deleted);
    --diffs-addition-color-override: var(--ck-palette-decoration-added);
    --diffs-gap-block: 0;
    --diffs-min-number-column-width: 4ch;
  }
}

