    --diffs-bg-separator-override: var(--ui-diff-divider-background);
    --diffs-bg-hover-override: var(--ui-diff-line-highlight);
    --diffs-bg: var(--ui-diff-background) !important;
    background-color: var(--ui-diff-background) !important;
  }

  :is([data-diff], [data-file]) [data-language-symbol-highlight] {
    background-color: var(
      --ck-palette-surface-button-secondary-hover
    ) !important;
  }

  :is([data-diff], [data-file]) [data-language-symbol-link] {
    text-decoration: underline;
    cursor: var(--ck-action-cursor);
  }

  :is([data-diff], [data-file]) [data-ck-utility-button] {
    background-color: var(--ck-palette-ink);
    color: var(--ck-palette-surface-surface-under);
    border: none;
    border-radius: 4px;
    margin-right: 0;
  }

  :is([data-diff], [data-file]) [data-ck-utility-button]:hover {
    background-color: color-mix(
      in srgb,
      var(--ck-palette-ink) 88%,
      var(--ck-palette-surface-surface-under)
    );
  }

  :is([data-diff], [data-file]) [data-selected-line][data-line-annotation] {
    background-color: var(--diffs-bg);
  }

  [data-placeholder][data-loading] {
    --ui-diff-skeleton-fill: color-mix(
      in srgb,
      var(--ck-palette-ink-tertiary) 10%,
      transparent
    );
    --ui-diff-skeleton-glint: color-mix(
      in srgb,
      var(--ck-palette-ink-tertiary) 16%,
      transparent
    );
    position: relative;
    overflow: hidden;
    background-image: linear-gradient(
      to right,
      var(--ui-diff-skeleton-fill) 0 82%,
      transparent 82%
    );
    background-position: 12px 8px;
    background-size: calc(100% - 24px) 22px;
    background-repeat: repeat-y;
  }

  [data-placeholder][data-loading]::before {
    content: "";
    position: absolute;
    inset: 8px 12px;
    background: linear-gradient(
      90deg,
      transparent 0%,
      var(--ui-diff-skeleton-glint) 50%,
      transparent 100%
    );
    transform: translateX(-100%);
    animation: ui-diff-skeleton-wave 3000ms linear infinite;
    mask-image: repeating-linear-gradient(
      to bottom,
      var(--ck-mask) 0 14px,
      transparent 14px 22px
    );
  }

  @media (prefers-reduced-motion: reduce) {
    [data-placeholder][data-loading]::before {
      animation: none;
    }
  }

  /* Preserve the pre-beta split-column width instead of reserving a scrollbar gutter in every pane. */
  :is([data-diff], [data-file]) [data-code] {
    scrollbar-gutter: auto;
  }

  :is([data-diff], [data-file])
    [data-line-type="change-addition"]:is([data-line], [data-ck-no-newline]) {
    --diffs-computed-diff-line-bg: var(--diffs-bg-addition);
  }

  :is([data-diff], [data-file])
    [data-line-type="change-addition"]:is(
      [data-ck-column-number],
      [data-gutter-buffer]
    ) {
    --diffs-computed-diff-line-bg: var(--ui-diff-added-gutter);
  }

  :is([data-diff], [data-file])
    [data-line-type="change-deletion"]:is([data-line], [data-ck-no-newline]) {
    --diffs-computed-diff-line-bg: var(--diffs-bg-deletion);
  }

  :is([data-diff], [data-file])
    [data-line-type="change-deletion"]:is(
      [data-ck-column-number],
      [data-gutter-buffer]
    ) {
    --diffs-computed-diff-line-bg: var(--ui-diff-removed-gutter);
  }

  :is([data-diff], [data-file])
    [data-line-type="change-addition"][data-hovered]:not([data-selected-line]) {
    --diffs-computed-hovered-line-bg: var(--ui-diff-added-highlight);
  }

  :is([data-diff], [data-file])
    [data-line-type="change-deletion"][data-hovered]:not([data-selected-line]) {
    --diffs-computed-hovered-line-bg: var(--ui-diff-removed-highlight);
  }

  :is([data-diff], [data-file])
    [data-line-type="change-deletion"][data-ck-column-number]::before {
    background-color: var(--diffs-deletion-base);
    background-image: none;
  }

  /* Cover fractional-pixel gaps between consecutive solid change markers. */
  :is([data-diff], [data-file])
    [data-line-type="change-addition"][data-ck-column-number]
    + [data-line-type="change-addition"][data-ck-column-number]::before,
  :is([data-diff], [data-file])
    [data-line-type="change-deletion"][data-ck-column-number]
    + [data-line-type="change-deletion"][data-ck-column-number]::before {
    contain: none;
    top: -1px;
    height: calc(100% + 1px);
  }

  /* alignCommentGutter */
  &.alignCommentGutter :is([data-diff], [data-file]) [data-ck-column-number] {
    padding-inline-start: calc(var(--spacing) * 10);
  }

  /* includeSimpleLineSeparators (:host(.composer-diff-simple-line)) */
  &.simpleLine [data-separator]:empty {
    background-color: transparent;
  }

  &.simpleLine [data-separator]:empty::after {
    content: "";
    grid-column: 2 / 3;
    align-self: center;
    margin-inline: 1ch;
    border-top: 1px solid color-mix(in srgb, var(--diffs-fg) 18%, transparent);
  }

  /* useReviewLineInfoSeparators */
  &.reviewLineInfo {
    :is([data-diff], [data-file]) [data-ck-column-number] {
      padding-inline: 1.5ch;
      text-align: center;
    }

    :is([data-diff], [data-file])
      [data-separator="line-info"]
      :is(
        [data-separator-wrapper],
        [data-ck-expand-button],
        [data-separator-content]
      ) {
      border-radius: 0;
    }

    :is([data-diff], [data-file])
      [data-separator="line-info"]
      [data-separator-wrapper] {
      padding: 0;
    }

    :is([data-diff], [data-file])
      [data-unified]
      [data-separator="line-info"]
      [data-separator-wrapper] {
      grid-template-columns: var(--diffs-column-number-width) minmax(0, 1fr);
    }

    :is([data-diff], [data-file])
      [data-unified]
      [data-separator="line-info"]
      [data-ck-expand-button] {
      min-width: 0;
    }

    /* Pierre duplicates split separators into each gutter and content cell. */
    :is([data-diff], [data-file])
      [data-deletions]
      [data-gutter]
      [data-separator="line-info"]
      [data-separator-wrapper] {
      background-color: var(--diffs-bg);
      grid-template-columns: minmax(0, 1fr);
    }

    :is([data-diff], [data-file])
      [data-deletions]
      [data-gutter]
      [data-separator="line-info"]
      [data-separator-content],
    :is([data-diff], [data-file])
      [data-deletions]
      [data-content]
      [data-separator="line-info"]
      [data-ck-expand-button] {
      display: none;
    }

    :is([data-diff], [data-file])
      [data-deletions]
      [data-content]
      [data-separator="line-info"]
      [data-separator-wrapper] {
      display: grid;
      grid-template-columns: minmax(0, 1fr);
    }

    :is([data-diff], [data-file])
      [data-deletions]
      [data-content]
      [data-separator="line-info"]
      [data-separator-content] {
      grid-column: 1;
    }

    :is([data-diff], [data-file])
      [data-additions]
      [data-gutter]
      [data-separator="line-info"],
    :is([data-diff], [data-file])
      [data-additions]
      [data-gutter]
      [data-separator="line-info"]
      [data-separator-wrapper] {
      background-color: var(--diffs-bg-separator);
    }

    :is([data-diff], [data-file])[data-overflow="scroll"]
      [data-additions]
      [data-gutter]
      [data-separator="line-info"]
      [data-separator-wrapper] {
      width: 100cqi;
    }

    :is([data-diff], [data-file])
      [data-additions]
      [data-content]
      [data-separator="line-info"]
      [data-separator-wrapper] {
      margin-inline-end: 0;
    }
  }
}

