/*
 * LoadingResultsShimmer:
 * the seeded loading bars of the diff placeholder.
 */
.shimmer {
  --ck-results-sweep-base: color-mix(
    in srgb,
    var(--ck-palette-ink-tertiary) 10%,
    transparent
  );
  --ck-results-sweep-highlight: color-mix(
    in srgb,
    var(--ck-palette-ink-tertiary) 16%,
    transparent
  );
  border-radius: var(--radius-md);
  background-color: var(--ck-results-sweep-base);
  position: relative;
  overflow: hidden;
  height: calc(var(--spacing) * 3.5);

  &::before {
    content: "";
    pointer-events: none;
    background: linear-gradient(
      90deg,
      transparent 0%,
      var(--ck-results-sweep-highlight) 50%,
      transparent 100%
    );
    will-change: transform;
    animation: ck-results-shimmer 3s linear infinite;
    animation-play-state: var(--ck-decoration-playback, running);
    animation-delay: var(--ck-results-sweep-delay, 0s);
    position: absolute;
    inset: 0;
    transform: translate(-100%);
