      <span className="sr-only">{messages.loadingDiff}</span>
      <ShimmerLines
        lines={Math.min(
          MAX_LOADING_LINES,
          Math.max(MIN_LOADING_LINES, additions + deletions + 6)
        )}
        maxWidth={96}
        minWidth={42}
        seed={`diff-loading-${name}-${additions}-${deletions}`}
      />
    </div>
  </div>
);

